navigation-morphing:
const MANIFEST = {
  "type": "Navigation.Morphing",
  "description": "Advanced navigation with SVG hamburger morphing, 12 menu effects, and sophisticated overlays",
  "editorElement": {
    "selector": ".morphing-navigation",
    "displayName": "Morphing Navigation",
    "archetype": "container",
    "data": {
      "menuItems": {
        "dataType": "text",
        "displayName": "Menu Items",
        "defaultValue": "Home,About,Work,Services,Contact",
        "group": "Content",
        "description": "Comma-separated menu items"
      },
      "logoText": {
        "dataType": "text",
        "displayName": "Logo Text",
        "defaultValue": "STUDIO",
        "group": "Content"
      },
      "menuType": {
        "dataType": "select",
        "displayName": "Menu Type",
        "defaultValue": "hamburger",
        "options": ["hamburger", "horizontal"],
        "group": "Layout"
      },
      "hamburgerStyle": {
        "dataType": "select",
        "displayName": "Hamburger Animation",
        "defaultValue": "svg-dash-1",
        "options": ["svg-dash-1", "svg-dash-2", "svg-dash-3", "svg-dash-4", "svg-dash-5", "svg-dash-6", "svg-dash-7", "svg-dash-8"],
        "group": "Animation"
      },
      "horizontalEffect": {
        "dataType": "select",
        "displayName": "Horizontal Menu Effect",
        "defaultValue": "border-scale-fill",
        "options": ["underline-slide", "background-pill", "border-top", "border-bottom", "scale-lift", "magnetic-pull", "floating-label", "stagger-reveal", "spotlight", "border-scale-fill", "svg-wave-underline", "dual-gradient"],
        "group": "Animation"
      },
      "overlayAnimation": {
        "dataType": "select",
        "displayName": "Overlay Animation",
        "defaultValue": "circular-reveal",
        "options": ["fullscreen-slide", "fullscreen-fade", "circular-reveal", "morphing-blob", "split-reveal", "bottom-sheet"],
        "group": "Animation"
      },
      "staggerDelay": {
        "dataType": "select",
        "displayName": "Stagger Delay (ms)",
        "defaultValue": "80",
        "options": ["40", "60", "80", "100", "120"],
        "group": "Animation"
      },
      "horizontalPosition": {
        "dataType": "select",
        "displayName": "Horizontal Position",
        "defaultValue": "top",
        "options": ["top", "bottom"],
        "group": "Layout"
      },
      "horizontalAlignment": {
        "dataType": "select",
        "displayName": "Menu Alignment",
        "defaultValue": "right",
        "options": ["left", "center", "right"],
        "group": "Layout"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "navBackground": {
        "dataType": "color",
        "displayName": "Nav Bar Background",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "overlayBackground": {
        "dataType": "color",
        "displayName": "Overlay Background",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "overlayTextColor": {
        "dataType": "color",
        "displayName": "Overlay Text Color",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "hamburgerColor": {
        "dataType": "color",
        "displayName": "Hamburger Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "gradientStart": {
        "dataType": "color",
        "displayName": "Gradient Start",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "gradientEnd": {
        "dataType": "color",
        "displayName": "Gradient End",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "menuFontSize": {
        "dataType": "number",
        "displayName": "Menu Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "overlayFontSize": {
        "dataType": "number",
        "displayName": "Overlay Font Size (px)",
        "defaultValue": 48,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "400",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.05em",
        "options": ["0em", "0.025em", "0.05em", "0.075em", "0.1em"],
        "group": "Typography"
      },
      "textTransform": {
        "dataType": "select",
        "displayName": "Text Transform",
        "defaultValue": "uppercase",
        "options": ["none", "uppercase", "lowercase", "capitalize"],
        "group": "Typography"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const menuItemsString = config?.menuItems || 'Home,About,Work,Services,Contact';
  const logoText = config?.logoText || 'STUDIO';
  const menuType = config?.menuType || 'hamburger';
  const hamburgerStyle = config?.hamburgerStyle || 'svg-dash-1';
  const horizontalEffect = config?.horizontalEffect || 'border-scale-fill';
  const overlayAnimation = config?.overlayAnimation || 'circular-reveal';
  const staggerDelay = parseInt(config?.staggerDelay || '80');
  const horizontalPosition = config?.horizontalPosition || 'top';
  const horizontalAlignment = config?.horizontalAlignment || 'right';
  const backgroundColor = config?.backgroundColor || '#FAFAFA';
  const navBackground = config?.navBackground || '#FFFFFF';
  const overlayBackground = config?.overlayBackground || '#18181B';
  const textColor = config?.textColor || '#18181B';
  const overlayTextColor = config?.overlayTextColor || '#FAFAFA';
  const accentColor = config?.accentColor || '#3F3F46';
  const hamburgerColor = config?.hamburgerColor || '#18181B';
  const gradientStart = config?.gradientStart || '#3F3F46';
  const gradientEnd = config?.gradientEnd || '#71717A';
  const menuFontSize = parseInt(config?.menuFontSize || '14');
  const overlayFontSize = parseInt(config?.overlayFontSize || '48');
  const fontWeight = config?.fontWeight || '400';
  const letterSpacing = config?.letterSpacing || '0.05em';
  const textTransform = config?.textTransform || 'uppercase';

  const menuItems = React.useMemo(() => {
    return menuItemsString.split(',').map(item => item.trim()).filter(Boolean);
  }, [menuItemsString]);

  const [isOpen, setIsOpen] = React.useState(false);
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [activeIndex, setActiveIndex] = React.useState(0);

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  React.useEffect(() => {
    if (menuType === 'hamburger' && isOpen) {
      const handleEscape = (e) => {
        if (e.key === 'Escape') setIsOpen(false);
      };
      window.addEventListener('keydown', handleEscape);
      return () => window.removeEventListener('keydown', handleEscape);
    }
  }, [isOpen, menuType]);

  const getSvgPaths = () => {
    const paths = {
      'svg-dash-1': {
        top: { d: "m 30,33 h 40 c 0,0 9.044436,-0.654587 9.044436,-8.508902 0,-7.854315 -8.024349,-11.958003 -14.89975,-10.85914 -6.875401,1.098863 -13.637059,4.171617 -13.637059,16.368042 v 40", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 30,50 h 40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 30,67 h 40 c 12.796276,0 15.357889,-11.717785 15.357889,-26.851538 0,-15.133752 -4.786586,-27.274118 -16.667516,-27.274118 -11.88093,0 -18.499247,6.994427 -18.435284,17.125656 l 0,40", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: true
      },
      'svg-dash-2': {
        top: { d: "m 30,33 h 40 c 3.722839,0 7.5,3.126468 7.5,8.578427 0,5.451959 -2.727029,8.421573 -7.5,8.421573 h -20", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 30,50 h 40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 70,67 h -40 c 0,0 -7.5,-0.802118 -7.5,-8.365747 0,-7.563629 7.5,-8.634253 7.5,-8.634253 h 20", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: false
      },
      'svg-dash-3': {
        top: { d: "m 70,33 h -40 c 0,0 -6,1.368796 -6,8.5 0,7.131204 6,8.5013 6,8.5013 h 20", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 30,50 h 40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 30,67 h 40 c 0,0 6,-1.368796 6,-8.5 0,-7.131204 -6,-8.5013 -6,-8.5013 h -20", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: false
      },
      'svg-dash-4': {
        top: { d: "m 30,33 h 40 c 0,0 8.5,-0.68551 8.5,10.375 0,8.292653 -6.122707,9.002293 -8.5,6.625 l -11.071429,-11.071429", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 30,50 h 40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 70,67 h -40 c 0,0 -8.5,0.68551 -8.5,-10.375 0,-8.292653 6.122707,-9.002293 8.5,-6.625 l 11.071429,11.071429", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: true
      },
      'svg-dash-5': {
        top: { d: "m 30,33 h 40 c 13.100415,0 14.380204,31.009071 -0.75,26.5 -14.166419,-4.22496 -15.975799,-30.5 -15.5,-48", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 30,50 h 40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 70,67 h -40 c -13.100415,0 -14.380204,-31.009071 0.75,-26.5 14.166419,4.22496 15.975799,30.5 15.5,48", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: false
      },
      'svg-dash-6': {
        top: { d: "m 30,33 h 40 c 3.722839,0 7.5,3.126468 7.5,8.578427 0,5.451959 -2.727029,8.421573 -7.5,8.421573 h -20", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 70,50 h -40 c -5.6862915,0 -8.534259,5.534817 -8.534259,11.65498 0,6.120163 2.848825,11.345019 8.534259,11.345019 h 20", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 30,67 h 40 c 5.686291,0 8.534259,-5.534817 8.534259,-11.654981 0,-6.120163 -2.848968,-11.345019 -8.534259,-11.345019 h -20", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: false
      },
      'svg-dash-7': {
        top: { d: "m 30,33 h 40 c 0,0 9.044436,-0.654587 9.044436,-8.508902 0,-7.854315 -8.024349,-11.958003 -14.89975,-10.85914 -6.875401,1.098863 -13.637059,4.171617 -13.637059,16.368042 v 40", dasharray: '40 139', closedOffset: '0', openOffset: '-98' },
        middle: { d: "m 70,50 c 0,0 -9.044436,0.654587 -9.044436,8.508902 0,7.854315 8.024349,11.958003 14.89975,10.85914 6.875401,-1.098863 13.637059,-4.171617 13.637059,-16.368042 v -40", dasharray: '40 142', closedOffset: '0', openOffset: '-20' },
        bottom: { d: "m 30,67 h 40 c 12.796276,0 15.357889,-11.717785 15.357889,-26.851538 0,-15.133752 -4.786586,-27.274118 -16.667516,-27.274118 -11.88093,0 -18.499247,6.994427 -18.435284,17.125656 l 0,40", dasharray: '40 85', closedOffset: '0', openOffset: '-68' },
        rotate: true
      },
      'svg-dash-8': {
        top: { d: "m 30,33 h 40", dasharray: '40 40', closedOffset: '0', openOffset: '0' },
        middle: { d: "m 30,50 h 40", dasharray: '40 40', closedOffset: '0', openOffset: '0', rotateIndependently: true },
        bottom: { d: "m 30,67 h 40", dasharray: '40 40', closedOffset: '0', openOffset: '0' },
        rotate: false
      }
    };
    return paths[hamburgerStyle] || paths['svg-dash-1'];
  };

  const renderSvgHamburger = () => {
    const paths = getSvgPaths();
    const shouldRotate = paths.rotate && isOpen;

    const lineStyle = {
      fill: 'none',
      stroke: hamburgerColor,
      strokeWidth: '5.5',
      strokeLinecap: 'round',
      transition: prefersReducedMotion ? 'none' : 'stroke-dasharray 400ms cubic-bezier(0.4, 0, 0.2, 1), stroke-dashoffset 400ms cubic-bezier(0.4, 0, 0.2, 1)'
    };

    return (
      <svg
        viewBox="0 0 100 100"
        width="40"
        height="40"
        onClick={() => setIsOpen(!isOpen)}
        style={{
          cursor: 'pointer',
          transform: shouldRotate ? 'rotate(45deg)' : 'rotate(0deg)',
          transition: prefersReducedMotion ? 'none' : 'transform 400ms cubic-bezier(0.4, 0, 0.2, 1)'
        }}
        aria-label={isOpen ? 'Close menu' : 'Open menu'}
        aria-expanded={isOpen}
        role="button"
        tabIndex={0}
        onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') setIsOpen(!isOpen); }}
      >
        <path
          style={{
            ...lineStyle,
            strokeDasharray: paths.top.dasharray,
            strokeDashoffset: isOpen ? paths.top.openOffset + 'px' : paths.top.closedOffset + 'px'
          }}
          d={paths.top.d}
        />
        <path
          style={{
            ...lineStyle,
            strokeDasharray: paths.middle.dasharray,
            strokeDashoffset: isOpen ? paths.middle.openOffset + 'px' : paths.middle.closedOffset + 'px',
            opacity: paths.middle.rotateIndependently ? 1 : (isOpen ? 0 : 1),
            transform: paths.middle.rotateIndependently && isOpen ? 'rotate(90deg)' : 'rotate(0deg)',
            transformOrigin: '50% 50%',
            transition: prefersReducedMotion ? 'none' : 'stroke-dasharray 400ms, stroke-dashoffset 400ms, opacity 400ms, transform 400ms'
          }}
          d={paths.middle.d}
        />
        <path
          style={{
            ...lineStyle,
            strokeDasharray: paths.bottom.dasharray,
            strokeDashoffset: isOpen ? paths.bottom.openOffset + 'px' : paths.bottom.closedOffset + 'px'
          }}
          d={paths.bottom.d}
        />
      </svg>
    );
  };

  const getOverlayStyle = () => {
    const baseStyle = {
      position: 'fixed',
      top: 0,
      left: 0,
      width: '100%',
      height: '100%',
      backgroundColor: overlayBackground,
      zIndex: 999,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      transition: prefersReducedMotion ? 'none' : 'all 500ms cubic-bezier(0.4, 0, 0.2, 1)'
    };

    const animations = {
      'fullscreen-slide': {
        transform: isOpen ? 'translateX(0)' : 'translateX(100%)',
        opacity: 1
      },
      'fullscreen-fade': {
        opacity: isOpen ? 0.98 : 0,
        pointerEvents: isOpen ? 'auto' : 'none'
      },
      'circular-reveal': {
        clipPath: isOpen ? 'circle(150%)' : 'circle(25px at calc(100% - 60px) 40px)'
      },
      'morphing-blob': {
        clipPath: isOpen ? 'circle(150%)' : 'circle(40px at calc(100% - 60px) 40px)',
        borderRadius: isOpen ? '0%' : '63% 37% 54% 46% / 55% 48% 52% 45%'
      },
      'split-reveal': {
        transform: isOpen ? 'translateY(0)' : 'translateY(-100%)'
      },
      'bottom-sheet': {
        top: 'auto',
        bottom: 0,
        height: isOpen ? '70vh' : '0',
        minHeight: isOpen ? '50vh' : '0',
        borderRadius: '24px 24px 0 0'
      }
    };

    return { ...baseStyle, ...animations[overlayAnimation] };
  };

  const getHorizontalItemStyle = (index) => {
    const isHovered = hoveredIndex === index;
    const isActive = activeIndex === index;
    const baseStyle = {
      position: 'relative',
      padding: '12px 20px',
      color: textColor,
      fontSize: `${menuFontSize}px`,
      fontWeight: fontWeight,
      letterSpacing: letterSpacing,
      textTransform: textTransform,
      textDecoration: 'none',
      cursor: 'pointer',
      transition: prefersReducedMotion ? 'none' : 'all 300ms ease-out',
      fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
    };

    const effects = {
      'underline-slide': {
        borderBottom: (isHovered || isActive) ? `2px solid ${accentColor}` : '2px solid transparent'
      },
      'background-pill': {
        backgroundColor: (isHovered || isActive) ? accentColor : 'transparent',
        borderRadius: '50px',
        color: (isHovered || isActive) ? navBackground : textColor
      },
      'border-top': {
        borderTop: (isHovered || isActive) ? `3px solid ${accentColor}` : '3px solid transparent',
        marginTop: '-3px'
      },
      'border-bottom': {
        borderBottom: (isHovered || isActive) ? `3px solid ${accentColor}` : '3px solid transparent'
      },
      'scale-lift': {
        transform: (isHovered || isActive) ? 'translateY(-3px) scale(1.05)' : 'none'
      },
      'magnetic-pull': {
        transform: isHovered ? 'scale(1.1)' : (isActive ? 'scale(1.05)' : 'scale(1)'),
        fontWeight: (isHovered || isActive) ? '500' : fontWeight
      },
      'floating-label': {
        transform: (isHovered || isActive) ? 'translateY(-5px)' : 'none'
      },
      'stagger-reveal': {
        backgroundColor: (isHovered || isActive) ? `${accentColor}20` : 'transparent',
        borderRadius: '4px'
      },
      'spotlight': {
        boxShadow: (isHovered || isActive) ? `0 0 20px ${accentColor}40, inset 0 0 20px ${accentColor}20` : 'none',
        backgroundColor: (isHovered || isActive) ? `${accentColor}10` : 'transparent',
        borderRadius: '8px'
      },
      'border-scale-fill': {
        backgroundColor: (isHovered || isActive) ? accentColor : 'transparent',
        color: (isHovered || isActive) ? navBackground : textColor,
        padding: '12px 20px'
      },
      'svg-wave-underline': {
        paddingBottom: '14px'
      },
      'dual-gradient': {}
    };

    return { ...baseStyle, ...effects[horizontalEffect] };
  };

  const renderHorizontalMenu = () => (
    <nav
      style={{
        position: 'fixed',
        [horizontalPosition]: 0,
        left: 0,
        right: 0,
        backgroundColor: navBackground,
        padding: '16px 40px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        boxShadow: '0 1px 3px rgba(0,0,0,0.05)',
        zIndex: 1000
      }}
    >
      <div
        style={{
          fontSize: '18px',
          fontWeight: '500',
          letterSpacing: '0.15em',
          color: textColor,
          fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
        }}
      >
        {logoText}
      </div>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '8px',
          marginLeft: horizontalAlignment === 'left' ? '0' : 'auto',
          marginRight: horizontalAlignment === 'right' ? '0' : (horizontalAlignment === 'center' ? 'auto' : undefined)
        }}
      >
        {menuItems.map((item, index) => (
          <button
            key={index}
            onClick={() => setActiveIndex(index)}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => setHoveredIndex(null)}
            aria-current={activeIndex === index ? 'page' : undefined}
            style={{
              ...getHorizontalItemStyle(index),
              background: 'none',
              border: 'none'
            }}
          >
            {item}
          </button>
        ))}
      </div>
    </nav>
  );

  const renderHamburgerMenu = () => (
    <>
      <nav
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          backgroundColor: isOpen ? 'transparent' : navBackground,
          padding: '16px 40px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          zIndex: 1001,
          transition: prefersReducedMotion ? 'none' : 'background-color 300ms ease-out'
        }}
      >
        <div
          style={{
            fontSize: '18px',
            fontWeight: '500',
            letterSpacing: '0.15em',
            color: isOpen ? overlayTextColor : textColor,
            fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
            transition: prefersReducedMotion ? 'none' : 'color 300ms ease-out'
          }}
        >
          {logoText}
        </div>
        <div style={{ filter: isOpen ? `brightness(0) invert(1)` : 'none', transition: prefersReducedMotion ? 'none' : 'filter 300ms ease-out' }}>
          {renderSvgHamburger()}
        </div>
      </nav>

      <div style={getOverlayStyle()}>
        <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '24px' }}>
          {menuItems.map((item, index) => (
            <button
              key={index}
              onClick={() => {
                setActiveIndex(index);
                setIsOpen(false);
              }}
              onMouseEnter={() => setHoveredIndex(index)}
              onMouseLeave={() => setHoveredIndex(null)}
              style={{
                background: 'none',
                border: 'none',
                color: overlayTextColor,
                fontSize: `clamp(32px, ${overlayFontSize}px, 8vw)`,
                fontWeight: fontWeight,
                letterSpacing: letterSpacing,
                textTransform: textTransform,
                cursor: 'pointer',
                opacity: isOpen ? 1 : 0,
                transform: isOpen ? 'translateY(0)' : 'translateY(30px)',
                transition: prefersReducedMotion ? 'none' : `all 400ms ease-out ${index * staggerDelay}ms`,
                fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
                position: 'relative'
              }}
              aria-current={activeIndex === index ? 'page' : undefined}
            >
              <span
                style={{
                  position: 'relative',
                  display: 'inline-block'
                }}
              >
                {item}
                <span
                  style={{
                    position: 'absolute',
                    bottom: '-4px',
                    left: 0,
                    width: hoveredIndex === index ? '100%' : '0%',
                    height: '2px',
                    backgroundColor: overlayTextColor,
                    transition: prefersReducedMotion ? 'none' : 'width 300ms ease-out'
                  }}
                />
              </span>
            </button>
          ))}
        </div>
      </div>
    </>
  );

  return (
    <div
      className="morphing-navigation"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '500px',
        backgroundColor: backgroundColor
      }}
    >
      {menuType === 'hamburger' ? renderHamburgerMenu() : renderHorizontalMenu()}

      <div
        style={{
          paddingTop: '120px',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '400px'
        }}
      >
        <div
          style={{
            textAlign: 'center',
            color: textColor,
            fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
          }}
        >
          <h1
            style={{
              fontSize: 'clamp(32px, 5vw, 64px)',
              fontWeight: '300',
              letterSpacing: '0.05em',
              margin: '0 0 16px 0'
            }}
          >
            {menuType === 'hamburger' ? 'Click the hamburger' : 'Hover the menu items'}
          </h1>
          <p
            style={{
              fontSize: '16px',
              opacity: 0.6,
              margin: 0
            }}
          >
            {menuType === 'hamburger' 
              ? `Animation: ${hamburgerStyle} • Overlay: ${overlayAnimation}`
              : `Effect: ${horizontalEffect}`
            }
          </p>
        </div>
      </div>
    </div>
  );
}

