      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const menuItemsString = config?.menuItems || 'Home,Search,Settings,Profile,Messages,Notifications';
  const menuIconsString = config?.menuIcons || '⌂,⌕,⚙,◉,✉,◔';
  const radius = parseInt(config?.radius || '140');
  const itemSize = parseInt(config?.itemSize || '56');
  const dockPosition = config?.dockPosition || 'bottom-right';
  const transitionStyle = config?.transitionStyle || 'stagger-scale';
  const staggerDelay = parseInt(config?.staggerDelay || '50');
  const rotationEnabled = config?.rotationEnabled === true;
  const rotationSpeed = parseInt(config?.rotationSpeed || '30');
  const backgroundColor = config?.backgroundColor || '#FAFAFA';
  const menuBackground = config?.menuBackground || '#18181B';
  const itemBackground = config?.itemBackground || '#27272A';
  const itemHoverBackground = config?.itemHoverBackground || '#3F3F46';
  const itemActiveBackground = config?.itemActiveBackground || '#52525B';
  const iconColor = config?.iconColor || '#FAFAFA';
  const toggleColor = config?.toggleColor || '#18181B';
  const toggleIconColor = config?.toggleIconColor || '#FAFAFA';
  const labelColor = config?.labelColor || '#FAFAFA';
  const labelFontSize = parseInt(config?.labelFontSize || '11');
  const iconFontSize = parseInt(config?.iconFontSize || '20');
  const fontWeight = config?.fontWeight || '400';

  const menuItems = React.useMemo(() => {
    const items = menuItemsString.split(',').map(item => item.trim()).filter(Boolean);
    const icons = menuIconsString.split(',').map(icon => icon.trim());
    return items.map((item, i) => ({
      label: item,
      icon: icons[i] || '●'
    }));
  }, [menuItemsString, menuIconsString]);

  const [isOpen, setIsOpen] = React.useState(false);
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [activeIndex, setActiveIndex] = React.useState(null);
  const [isPaused, setIsPaused] = React.useState(false);

  const prefersReducedMotion = React.useMemo(() => {
    return typeof window !== 'undefined'
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches
      : false;
  }, []);

  const uniqueId = React.useMemo(() => {
    return `radial-${Math.random().toString(36).substr(2, 9)}`;
  }, []);

  const getDockStyles = () => {
    const margin = 40;
    const positions = {
      'left': { left: margin, top: '50%', transform: 'translateY(-50%)' },
      'right': { right: margin, top: '50%', transform: 'translateY(-50%)' },
      'top': { top: margin, left: '50%', transform: 'translateX(-50%)' },
      'bottom': { bottom: margin, left: '50%', transform: 'translateX(-50%)' },
      'top-left': { top: margin, left: margin, transform: 'none' },
      'top-right': { top: margin, right: margin, transform: 'none' },
      'bottom-left': { bottom: margin, left: margin, transform: 'none' },
      'bottom-right': { bottom: margin, right: margin, transform: 'none' }
    };
    return positions[dockPosition] || positions['bottom-right'];
  };

  const getArcRange = () => {
    const ranges = {
      'left': { start: -90, end: 90 },
      'right': { start: 90, end: 270 },
      'top': { start: 0, end: 180 },
      'bottom': { start: 180, end: 360 },
      'top-left': { start: 0, end: 90 },
      'top-right': { start: 90, end: 180 },
      'bottom-left': { start: 270, end: 360 },
      'bottom-right': { start: 180, end: 270 }
    };
    return ranges[dockPosition] || ranges['bottom-right'];
  };

  const getItemPosition = (index) => {
    const totalItems = menuItems.length;
    const { start, end } = getArcRange();
    const arcSpan = end - start;
    const angleStep = arcSpan / (totalItems + 1);
    const angle = start + angleStep * (index + 1);
    const angleRad = (angle * Math.PI) / 180;

    const x = Math.cos(angleRad) * radius;
    const y = Math.sin(angleRad) * radius;

    return { x, y, angle };
  };

  const getItemTransitionStyle = (index, position) => {
    const baseDelay = index * staggerDelay;

    const transitions = {
      'fade': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${isOpen ? position.x : 0}px, ${isOpen ? position.y : 0}px)`,
        transition: prefersReducedMotion ? 'none' : `all 300ms ease-out ${baseDelay}ms`
      },
      'stagger-scale': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${isOpen ? position.x : 0}px, ${isOpen ? position.y : 0}px) scale(${isOpen ? 1 : 0.3})`,
        transition: prefersReducedMotion ? 'none' : `all 400ms cubic-bezier(0.34, 1.56, 0.64, 1) ${baseDelay}ms`
      },
      'circle-expand': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${position.x}px, ${position.y}px) scale(${isOpen ? 1 : 0})`,
        transition: prefersReducedMotion ? 'none' : `all 400ms cubic-bezier(0.22, 1, 0.36, 1) ${baseDelay}ms`
      },
      'slide-rotate': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${isOpen ? position.x : position.x * 0.3}px, ${isOpen ? position.y : position.y * 0.3}px) rotate(${isOpen ? 0 : 180}deg)`,
        transition: prefersReducedMotion ? 'none' : `all 500ms cubic-bezier(0.34, 1.56, 0.64, 1) ${baseDelay}ms`
      },
      'wave': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${isOpen ? position.x : 0}px, ${isOpen ? position.y : 20}px)`,
        transition: prefersReducedMotion ? 'none' : `all 400ms cubic-bezier(0.34, 1.56, 0.64, 1) ${baseDelay + Math.sin(index * 0.5) * 50}ms`
      },
      'elastic': {
        opacity: isOpen ? 1 : 0,
        transform: `translate(${isOpen ? position.x : 0}px, ${isOpen ? position.y : 0}px) scale(${isOpen ? 1 : 0})`,
        transition: prefersReducedMotion ? 'none' : `opacity 300ms ease-out ${baseDelay}ms, transform 600ms cubic-bezier(0.68, -0.55, 0.265, 1.55) ${baseDelay}ms`
      }
    };

    return transitions[transitionStyle] || transitions['stagger-scale'];
  };

  const getContainerTransitionStyle = () => {
    const base = {
      clipPath: isOpen ? 'circle(200%)' : 'circle(28px)',
      transition: prefersReducedMotion ? 'none' : 'clip-path 400ms cubic-bezier(0.22, 1, 0.36, 1)'
    };

    if (transitionStyle === 'circle-expand') {
      return base;
    }

    return {
      clipPath: 'none',
      opacity: 1
    };
  };

  return (
    <div
      className="radial-command"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '500px',
        backgroundColor: backgroundColor,
        overflow: 'hidden'
      }}
    >
      <div
        style={{
          position: 'absolute',
          ...getDockStyles(),
          zIndex: 1000
        }}
      >
        <div
          style={{
            position: 'relative',
            width: itemSize + 8,
            height: itemSize + 8
          }}
          onMouseEnter={() => setIsPaused(true)}
          onMouseLeave={() => setIsPaused(false)}
        >
          <div
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: radius * 2 + itemSize,
              height: radius * 2 + itemSize,
              backgroundColor: menuBackground,
              borderRadius: '50%',
              ...getContainerTransitionStyle(),
              pointerEvents: isOpen ? 'auto' : 'none'
            }}
          >
            <div
              style={{
                position: 'absolute',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                animation: rotationEnabled && isOpen && !isPaused && !prefersReducedMotion
                  ? `${uniqueId}-rotate ${rotationSpeed}s linear infinite`
                  : 'none'
              }}
            >
              {menuItems.map((item, index) => {
                const position = getItemPosition(index);
                const isHovered = hoveredIndex === index;
                const isActive = activeIndex === index;

                return (
                  <button
                    key={index}
                    onClick={() => setActiveIndex(index)}
                    onMouseEnter={() => setHoveredIndex(index)}
                    onMouseLeave={() => setHoveredIndex(null)}
                    style={{
                      position: 'absolute',
                      left: '50%',
                      top: '50%',
                      marginLeft: -itemSize / 2,
                      marginTop: -itemSize / 2,
                      width: itemSize,
                      height: itemSize,
                      borderRadius: '50%',
                      backgroundColor: isActive ? itemActiveBackground : (isHovered ? itemHoverBackground : itemBackground),
                      border: 'none',
                      cursor: 'pointer',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      gap: '4px',
                      ...getItemTransitionStyle(index, position),
                      transformOrigin: '0 0'
                    }}
                    aria-label={item.label}
                  >
                    <span
                      style={{
                        fontSize: iconFontSize,
                        color: iconColor,
                        lineHeight: 1,
                        transform: rotationEnabled && isOpen && !isPaused ? `rotate(-${(Date.now() / 1000 / rotationSpeed * 360) % 360}deg)` : 'none'
                      }}
                    >
                      {item.icon}
                    </span>
                  </button>
                );
              })}
            </div>
          </div>

          <button
            onClick={() => setIsOpen(!isOpen)}
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              transform: 'translate(-50%, -50%)',
              width: itemSize + 8,
              height: itemSize + 8,
              borderRadius: '50%',
              backgroundColor: toggleColor,
              border: 'none',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              boxShadow: '0 4px 20px rgba(0,0,0,0.2)',
              zIndex: 10,
              transition: prefersReducedMotion ? 'none' : 'transform 300ms ease-out, box-shadow 300ms ease-out'
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1.05)';
              e.currentTarget.style.boxShadow = '0 6px 24px rgba(0,0,0,0.25)';
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.transform = 'translate(-50%, -50%) scale(1)';
              e.currentTarget.style.boxShadow = '0 4px 20px rgba(0,0,0,0.2)';
            }}
            aria-label={isOpen ? 'Close menu' : 'Open menu'}
            aria-expanded={isOpen}
          >
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke={toggleIconColor}
              strokeWidth="2"
              strokeLinecap="round"
              style={{
                transform: isOpen ? 'rotate(45deg)' : 'rotate(0deg)',
                transition: prefersReducedMotion ? 'none' : 'transform 300ms cubic-bezier(0.34, 1.56, 0.64, 1)'
              }}
            >
              <line x1="12" y1="5" x2="12" y2="19" />
              <line x1="5" y1="12" x2="19" y2="12" />
            </svg>
          </button>
        </div>
      </div>

      {hoveredIndex !== null && isOpen && (
        <div
          style={{
            position: 'absolute',
            ...getDockStyles(),
            transform: 'translate(-50%, -150%)',
            backgroundColor: menuBackground,
            color: labelColor,
            padding: '8px 16px',
            borderRadius: '4px',
            fontSize: labelFontSize,
            fontWeight: fontWeight,
            letterSpacing: '0.05em',
            textTransform: 'uppercase',
            whiteSpace: 'nowrap',
            fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',
            boxShadow: '0 4px 12px rgba(0,0,0,0.15)',
            pointerEvents: 'none',
            opacity: 1,
            transition: prefersReducedMotion ? 'none' : 'opacity 200ms ease-out',
            zIndex: 1001
          }}
        >
          {menuItems[hoveredIndex]?.label}
        </div>
      )}

      <div
        style={{
          position: 'absolute',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          textAlign: 'center',
          color: '#71717A',
          fontFamily: 'system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif'
        }}
      >
        <h2
          style={{
            fontSize: '32px',
            fontWeight: '300',
            letterSpacing: '0.05em',
            margin: '0 0 12px 0',
            color: '#18181B'
          }}
        >
          Radial Command
        </h2>
        <p style={{ margin: 0, fontSize: '14px' }}>
          Click the button in the {dockPosition.replace('-', ' ')} corner
        </p>
        <p style={{ margin: '8px 0 0 0', fontSize: '12px', opacity: 0.6 }}>
          Transition: {transitionStyle} • Items: {menuItems.length}
        </p>
      </div>

      <style>
        {`
          @keyframes ${uniqueId}-rotate {
            from { transform: translate(-50%, -50%) rotate(0deg); }
            to { transform: translate(-50%, -50%) rotate(360deg); }
          }
        `}
      </style>
    </div>
  );
}

