  var tabRefs = React.useRef([]);

  var _indicatorStyle = React.useState({ left: 0, width: 0 });
  var indicator = _indicatorStyle[0];
  var setIndicator = _indicatorStyle[1];

  React.useEffect(function() {
    var activeTabEl = tabRefs.current[activeTab];
    if (activeTabEl) {
      setIndicator({
        left: activeTabEl.offsetLeft,
        width: activeTabEl.offsetWidth
      });
    }
  }, [activeTab, tabs.length]);

  var handleTabClick = function(index) {
    if (index !== activeTab) {
      setActiveTab(index);
