const MANIFEST = {
  "type": "Navigation.BottomGlassNav",
  "description": "Award-winning bottom-docked glass navigation with fluid morphing, magnetic hover effects, and advanced micro-interactions",
  "editorElement": {
    "selector": ".bottom-glass-nav",
    "displayName": "Bottom Glass Navigation",
    "archetype": "container",
    "data": {
      "navItems": {
        "dataType": "text",
        "displayName": "Navigation Items (Label|Description|Icon)",
        "defaultValue": "Home|Welcome to our space|○,Work|Creative projects|◐,Services|What we offer|◑,About|Our story|◕,Contact|Get in touch|●",
        "group": "Content"
      },
      "enableMagneticEffect": {
        "dataType": "booleanValue",
        "displayName": "Magnetic Hover Effect",
        "defaultValue": true,
        "group": "Animation"
      },
      "enableRipple": {
        "dataType": "booleanValue",
        "displayName": "Click Ripple Effect",
        "defaultValue": true,
        "group": "Animation"
      },
      "enableParallax": {
        "dataType": "booleanValue",
        "displayName": "Scroll Parallax",
        "defaultValue": true,
        "group": "Animation"
      },
      "morphingIntensity": {
        "dataType": "select",
        "displayName": "Morphing Intensity",
        "defaultValue": "high",
        "options": ["subtle", "medium", "high", "extreme"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#E5E5E5",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "accentColor": {
        "dataType": "color",
        "displayName": "Accent Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "glowColor": {
        "dataType": "color",
        "displayName": "Glow Effect Color",
        "defaultValue": "#000000",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 13,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "400",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "blurAmount": {
        "dataType": "select",
        "displayName": "Backdrop Blur",
        "defaultValue": "24px",
        "options": ["16px", "20px", "24px", "32px", "40px"],
        "group": "Glass Effect"
      }
    }
  }
};

function Component({ config = {} }) {
  const [activeIndex, setActiveIndex] = React.useState(0);
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [mousePos, setMousePos] = React.useState({ x: 0, y: 0 });
  const [scrollY, setScrollY] = React.useState(0);
  const [ripples, setRipples] = React.useState([]);
  const navRef = React.useRef(null);
  const itemRefs = React.useRef([]);

  const navItems = (config?.navItems || MANIFEST.editorElement.data.navItems.defaultValue)
    .split(',')
    .map(item => {
      const [label, description, icon] = item.split('|');
      return { label: label?.trim() || '', description: description?.trim() || '', icon: icon?.trim() || '●' };
    });

  const enableMagneticEffect = config?.enableMagneticEffect !== false;
  const enableRipple = config?.enableRipple !== false;
  const enableParallax = config?.enableParallax !== false;
  const morphingIntensity = config?.morphingIntensity || 'high';
  const backgroundColor = config?.backgroundColor || '#E5E5E5';
  const textColor = config?.textColor || '#000000';
  const accentColor = config?.accentColor || '#000000';
  const glowColor = config?.glowColor || '#000000';
  const fontSize = parseInt(config?.fontSize || '13');
  const fontWeight = config?.fontWeight || '400';
  const blurAmount = config?.blurAmount || '24px';

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  const morphingValues = {
    subtle: { padding: 1.2, radius: 0.8 },
    medium: { padding: 1.5, radius: 1.2 },
    high: { padding: 2, radius: 1.5 },
    extreme: { padding: 2.5, radius: 2 }
  };

  const morphing = morphingValues[morphingIntensity] || morphingValues.high;

  const hexToRgba = (hex, alpha) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  };

  // Scroll parallax effect
  React.useEffect(() => {
    if (!enableParallax || prefersReducedMotion) return;

    const handleScroll = () => {
      const scrolled = window.scrollY;
      setScrollY(scrolled);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, [enableParallax, prefersReducedMotion]);

  // Magnetic effect on mouse move
  const handleMouseMove = (e, index) => {
    if (!enableMagneticEffect || prefersReducedMotion) return;

    const item = itemRefs.current[index];
    if (!item) return;

    const rect = item.getBoundingClientRect();
    const x = e.clientX - (rect.left + rect.width / 2);
    const y = e.clientY - (rect.top + rect.height / 2);

    const distance = Math.sqrt(x * x + y * y);
    const maxDistance = 100;

    if (distance < maxDistance) {
      const intensity = 1 - (distance / maxDistance);
      const moveX = (x / rect.width) * 12 * intensity;
      const moveY = (y / rect.height) * 12 * intensity;

      setMousePos({ x: moveX, y: moveY });
    } else {
      setMousePos({ x: 0, y: 0 });
    }
  };

  const handleMouseLeave = () => {
    setMousePos({ x: 0, y: 0 });
  };

  // Ripple effect on click
  const handleClick = (index, e) => {
    setActiveIndex(index);

    if (!enableRipple || prefersReducedMotion) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const ripple = {
      id: Date.now(),
      x,
      y,
      index
    };

    setRipples(prev => [...prev, ripple]);

    setTimeout(() => {
      setRipples(prev => prev.filter(r => r.id !== ripple.id));
    }, 800);
  };

  const parallaxOffset = enableParallax ? Math.min(scrollY * 0.3, 50) : 0;

  return (
    <nav 
      ref={navRef}
      style={{
        position: 'fixed',
        bottom: `calc(1rem + ${parallaxOffset}px)`,
        left: '50%',
        transform: `translateX(-50%) translateY(${prefersReducedMotion ? 0 : Math.sin(Date.now() / 3000) * 2}px)`,
        zIndex: 1000,
        display: 'flex',
        alignItems: 'center',
        gap: '0.25rem',
        padding: '0.375rem 0.875rem',
        borderRadius: '9999px',
        backdropFilter: prefersReducedMotion ? 'none' : `blur(${blurAmount}) saturate(180%)`,
        WebkitBackdropFilter: prefersReducedMotion ? 'none' : `blur(${blurAmount}) saturate(180%)`,
        backgroundColor: hexToRgba(backgroundColor, 0.4),
        border: `1px solid ${hexToRgba(textColor, 0.08)}`,
        boxShadow: prefersReducedMotion ? 'none' : `
          0 8px 32px ${hexToRgba(glowColor, 0.12)},
          0 2px 8px ${hexToRgba(glowColor, 0.08)},
          inset 0 1px 0 ${hexToRgba('#FFFFFF', 0.1)}
        `,
        willChange: 'transform',
        transition: 'bottom 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
      }}
    >
      {navItems.map((item, index) => {
        const isActive = index === activeIndex;
        const isHovered = index === hoveredIndex;
        const isExpanded = isHovered || isActive;

        const itemRipples = ripples.filter(r => r.index === index);

        return (
          <div
            key={index}
            ref={el => itemRefs.current[index] = el}
            onClick={(e) => handleClick(index, e)}
            onMouseEnter={() => setHoveredIndex(index)}
            onMouseLeave={() => {
              setHoveredIndex(null);
              handleMouseLeave();
            }}
            onMouseMove={(e) => handleMouseMove(e, index)}
            style={{
              position: 'relative',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              padding: isExpanded ? `${0.625 * morphing.padding}rem ${1.25 * morphing.padding}rem` : '0.5rem 0.875rem',
              borderRadius: isExpanded ? `${0.875 * morphing.radius}rem` : '9999px',
              cursor: 'pointer',
              transition: prefersReducedMotion ? 'none' : `
                all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1),
                transform 0.2s cubic-bezier(0.34, 1.56, 0.64, 1)
              `,
              color: isActive ? accentColor : textColor,
              fontSize: `${fontSize}px`,
              fontWeight: isActive ? '500' : fontWeight,
              userSelect: 'none',
              overflow: 'visible',
              transform: prefersReducedMotion ? 'none' : `
                translate(${isHovered && enableMagneticEffect ? mousePos.x : 0}px, ${isHovered && enableMagneticEffect ? mousePos.y : 0}px)
                scale(${isActive ? 1.05 : isHovered ? 1.02 : 1})
              `,
            }}
          >
            {/* Glow effect on hover */}
            <span style={{
              position: 'absolute',
              inset: '-8px',
              background: `radial-gradient(circle at center, ${hexToRgba(glowColor, isHovered ? 0.15 : 0)} 0%, transparent 70%)`,
              borderRadius: 'inherit',
              pointerEvents: 'none',
              opacity: isHovered ? 1 : 0,
              transition: prefersReducedMotion ? 'none' : 'opacity 0.4s ease',
              filter: 'blur(8px)',
            }} />

            {/* Border layer with glow */}
            <span style={{
              position: 'absolute',
              inset: 0,
              border: `1px solid ${hexToRgba(isActive ? accentColor : textColor, isHovered || isActive ? 0.2 : 0)}`,
              borderRadius: 'inherit',
              pointerEvents: 'none',
              transition: prefersReducedMotion ? 'none' : 'all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
              boxShadow: isActive ? `0 0 20px ${hexToRgba(accentColor, 0.3)}, inset 0 1px 0 ${hexToRgba('#FFFFFF', 0.2)}` : 'none',
            }} />

            {/* Background tint with gradient */}
            <span style={{
              position: 'absolute',
              inset: 0,
              background: isActive 
                ? `linear-gradient(135deg, ${hexToRgba(accentColor, 0.08)} 0%, ${hexToRgba(accentColor, 0.04)} 100%)`
                : isHovered 
                  ? hexToRgba(textColor, 0.04) 
                  : 'transparent',
              borderRadius: 'inherit',
              pointerEvents: 'none',
              transition: prefersReducedMotion ? 'none' : 'all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
            }} />

            {/* Ripple effects */}
            {itemRipples.map(ripple => (
              <span
                key={ripple.id}
                style={{
                  position: 'absolute',
                  left: ripple.x,
                  top: ripple.y,
                  width: '4px',
                  height: '4px',
                  borderRadius: '50%',
                  backgroundColor: hexToRgba(accentColor, 0.4),
                  transform: 'translate(-50%, -50%) scale(0)',
                  animation: prefersReducedMotion ? 'none' : 'ripple 0.8s cubic-bezier(0.4, 0, 0.2, 1)',
                  pointerEvents: 'none',
                }}
              />
            ))}

            {/* Icon with rotation on hover */}
            <span style={{
              position: 'relative',
              zIndex: 1,
              fontSize: '16px',
              opacity: isActive || isHovered ? 1 : 0.6,
              transform: prefersReducedMotion ? 'none' : `rotate(${isHovered ? 180 : 0}deg) scale(${isActive ? 1.1 : 1})`,
              transition: prefersReducedMotion ? 'none' : 'all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
              display: 'block',
              marginBottom: isExpanded ? '0.25rem' : '0',
            }}>
              {item.icon}
            </span>

            {/* Label with slide-up animation */}
            <span style={{
              position: 'relative',
              zIndex: 1,
              opacity: prefersReducedMotion ? 1 : (isActive || isHovered ? 1 : 0.5),
              transition: prefersReducedMotion ? 'none' : 'all 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)',
              transform: prefersReducedMotion ? 'none' : `translateY(${isExpanded ? 0 : 2}px)`,
              fontWeight: isActive ? '500' : fontWeight,
              letterSpacing: isActive ? '0.02em' : '0',
            }}>
              {item.label}
            </span>

            {/* Description with elastic reveal */}
            {item.description && (
              <span style={{
                position: 'relative',
                zIndex: 1,
                opacity: prefersReducedMotion ? (isHovered ? 1 : 0) : (isHovered ? 1 : 0),
                maxHeight: isHovered ? '100px' : '0',
                marginTop: isHovered ? '0.375rem' : '0',
                fontSize: `${fontSize - 2}px`,
                fontWeight: '300',
                transition: prefersReducedMotion ? 'none' : `
                  opacity 0.4s cubic-bezier(0.34, 1.56, 0.64, 1) 0.1s,
                  max-height 0.6s cubic-bezier(0.34, 1.56, 0.64, 1),
                  margin-top 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)
                `,
                overflow: 'hidden',
                textAlign: 'center',
                whiteSpace: 'nowrap',
                color: hexToRgba(textColor, 0.7),
              }}>
                {item.description}
              </span>
            )}
          </div>
        );
      })}

      <style>{`
        @keyframes ripple {
          to {
            transform: translate(-50%, -50%) scale(40);
            opacity: 0;
          }
        }
      `}</style>
    </nav>
  );
}

