        "dataType": "select",
        "displayName": "Entrance Transition",
        "defaultValue": "stagger",
        "options": ["fade", "stagger", "circle-expand", "zoom-blur"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "centerButtonColor": {
        "dataType": "color",
        "displayName": "Center Button Color",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "centerButtonHoverColor": {
        "dataType": "color",
        "displayName": "Center Button Hover",
        "defaultValue": "#27272A",
        "group": "Colors"
      },
      "itemBackgroundColor": {
        "dataType": "color",
        "displayName": "Menu Item Background",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "itemTextColor": {
        "dataType": "color",
        "displayName": "Menu Item Text",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "rippleColor": {
        "dataType": "color",
        "displayName": "Ripple Effect Color",
        "defaultValue": "#71717A",
        "group": "Colors"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
