        "defaultValue": "60",
        "options": ["50", "60", "70", "80"],
        "group": "Layout"
      },
      "fontSize": {
        "dataType": "number",
        "displayName": "Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "fontWeight": {
        "dataType": "select",
        "displayName": "Font Weight",
        "defaultValue": "400",
        "options": ["300", "400", "500"],
        "group": "Typography"
      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.025em",
        "options": ["0em", "0.025em", "0.05em", "0.075em"],
        "group": "Typography"
      },
