        "dataType": "color",
        "displayName": "Toggle Button Background",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const menuItems = (config?.menuItems || "Home,About,Services,Portfolio,Team,Contact,Blog,Careers").split(',').map(item => item.trim());
  const showLabels = config?.showLabels !== false;
  const dockPosition = config?.dockPosition || "left";
  const mobileDockPosition = config?.mobileDockPosition || "bottom";
  const radius = parseInt(config?.radius || "300");
  const rotationSpeed = parseInt(config?.rotationSpeed || "60");
  const transitionStyle = config?.transitionStyle || "fade";
  const toggleIcon = config?.toggleIcon || "☰";
  const itemSize = parseInt(config?.itemSize || "60");
  const fontSize = parseInt(config?.fontSize || "14");
  const fontWeight = config?.fontWeight || "400";
  const letterSpacing = config?.letterSpacing || "0.025em";
  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const itemBackgroundColor = config?.itemBackgroundColor || "#F8F9FA";
  const itemBorderColor = config?.itemBorderColor || "#E9ECEF";
  const textColor = config?.textColor || "#212529";
  const activeItemColor = config?.activeItemColor || "#212529";
  const activeTextColor = config?.activeTextColor || "#FFFFFF";
  const toggleButtonColor = config?.toggleButtonColor || "#212529";
  const toggleButtonBackground = config?.toggleButtonBackground || "#F8F9FA";

  const [isOpen, setIsOpen] = React.useState(false);
  const [isPaused, setIsPaused] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(0);
  const [isMobile, setIsMobile] = React.useState(false);

  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  React.useEffect(() => {
    const checkMobile = () => {
      setIsMobile(window.innerWidth < 768);
    };
    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  const currentDockPosition = isMobile ? mobileDockPosition : dockPosition;

  const getDockStyles = (position, rad) => {
    const positions = {
      'left': { left: -rad + 'px', top: '50%', transform: 'translateY(-50%)' },
      'right': { right: -rad + 'px', top: '50%', transform: 'translateY(-50%)' },
      'top': { top: -rad + 'px', left: '50%', transform: 'translateX(-50%)' },
      'bottom': { bottom: -rad + 'px', left: '50%', transform: 'translateX(-50%)' },
      'top-left': { top: -rad + 'px', left: -rad + 'px', transform: 'none' },
      'top-right': { top: -rad + 'px', right: -rad + 'px', transform: 'none' },
      'bottom-left': { bottom: -rad + 'px', left: -rad + 'px', transform: 'none' },
      'bottom-right': { bottom: -rad + 'px', right: -rad + 'px', transform: 'none' }
    };
    return positions[position] || positions.left;
  };

  const dockStyles = getDockStyles(currentDockPosition, radius);

  const getItemTransform = (index) => {
    const angle = (360 / menuItems.length) * index;
    return `rotate(${angle}deg) translateX(${radius}px) rotate(-${angle}deg)`;
  };

  const getItemTransition = (index) => {
    const middle = Math.floor(menuItems.length / 2);

    switch (transitionStyle) {
      case 'stagger':
        return {
          transitionDelay: `${index * 50}ms`,
          opacity: isOpen ? 1 : 0
        };
      case 'wave':
        return {
          transitionDelay: `${Math.abs(index - middle) * 40}ms`,
          opacity: isOpen ? 1 : 0
        };
      default:
        return { opacity: isOpen ? 1 : 0 };
    }
  };

  return (
    <div className="radial-menu" style={{
      width: '100%',
      minHeight: '100vh',
      backgroundColor,
      position: 'relative',
      overflow: 'hidden'
    }}>
      {/* Toggle Button */}
      <button
        onClick={() => setIsOpen(!isOpen)}
        aria-expanded={isOpen}
        aria-label={isOpen ? "Close navigation menu" : "Open navigation menu"}
        style={{
          position: 'fixed',
          ...dockStyles,
          width: `${itemSize}px`,
          height: `${itemSize}px`,
          borderRadius: '50%',
          backgroundColor: toggleButtonBackground,
          border: `1px solid ${itemBorderColor}`,
          color: toggleButtonColor,
          fontSize: `${fontSize + 6}px`,
          cursor: 'pointer',
          zIndex: 1002,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          transition: 'all 300ms ease-out',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)'
        }}
        onMouseEnter={(e) => {
          e.currentTarget.style.transform = dockStyles.transform ? dockStyles.transform + ' scale(1.05)' : 'scale(1.05)';
        }}
        onMouseLeave={(e) => {
          e.currentTarget.style.transform = dockStyles.transform || 'none';
        }}
      >
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: '3px',
          width: '20px'
        }}>
          <span style={{
            width: '100%',
            height: '2px',
            backgroundColor: toggleButtonColor,
            transition: 'all 300ms ease-out',
            transformOrigin: 'center',
            transform: isOpen ? 'translateY(5px) rotate(45deg)' : 'translateY(0) rotate(0)'
          }} />
          <span style={{
            width: '100%',
            height: '2px',
            backgroundColor: toggleButtonColor,
            transition: 'all 300ms ease-out',
            opacity: isOpen ? 0 : 1
          }} />
          <span style={{
            width: '100%',
            height: '2px',
            backgroundColor: toggleButtonColor,
            transition: 'all 300ms ease-out',
            transformOrigin: 'center',
            transform: isOpen ? 'translateY(-11px) rotate(-45deg)' : 'translateY(0) rotate(0)'
          }} />
        </div>
      </button>

      {/* Circular Menu Container */}
      <div
        onMouseEnter={() => setIsPaused(true)}
        onMouseLeave={() => setIsPaused(false)}
        style={{
          position: 'fixed',
          ...dockStyles,
          width: `${radius * 2}px`,
          height: `${radius * 2}px`,
          zIndex: 1001,
          pointerEvents: isOpen ? 'auto' : 'none',
          ...(transitionStyle === 'circleExpand' && {
            clipPath: isOpen ? `circle(${radius * 2.5}px at center)` : 'circle(0px at center)',
            transition: 'clip-path 500ms ease-out'
          }),
          ...(transitionStyle === 'slideRotate' && {
            transform: isOpen 
              ? (dockStyles.transform ? dockStyles.transform + ' rotate(0) scale(1)' : 'rotate(0) scale(1)')
              : (dockStyles.transform ? dockStyles.transform + ' rotate(-90deg) scale(0.5)' : 'rotate(-90deg) scale(0.5)'),
            opacity: isOpen ? 1 : 0,
            transition: 'all 400ms ease-out'
          }),
          ...(transitionStyle === 'zoomBlur' && {
            transform: isOpen
              ? (dockStyles.transform ? dockStyles.transform + ' scale(1)' : 'scale(1)')
              : (dockStyles.transform ? dockStyles.transform + ' scale(0.3)' : 'scale(0.3)'),
            filter: isOpen ? 'blur(0)' : 'blur(20px)',
            opacity: isOpen ? 1 : 0,
            transition: 'all 500ms ease-out'
          }),
          ...((!['circleExpand', 'slideRotate', 'zoomBlur'].includes(transitionStyle)) && {
            opacity: isOpen ? 1 : 0,
            transition: 'opacity 300ms ease-out'
          })
        }}
      >
        <div style={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          width: 0,
          height: 0,
          transform: 'translate(-50%, -50%)',
          ...(rotationSpeed > 0 && !prefersReducedMotion && {
            animation: `rotateCircle ${rotationSpeed}s linear infinite`,
            animationPlayState: isPaused ? 'paused' : 'running'
          })
        }}>
          {menuItems.map((item, index) => {
            const itemTransition = getItemTransition(index);
            return (
              <button
                key={index}
                onClick={() => setActiveIndex(index)}
                aria-current={activeIndex === index ? "page" : undefined}
                style={{
                  position: 'absolute',
                  left: 0,
                  top: 0,
                  width: `${itemSize}px`,
                  height: `${itemSize}px`,
                  borderRadius: '50%',
                  backgroundColor: activeIndex === index ? activeItemColor : itemBackgroundColor,
                  border: `1px solid ${itemBorderColor}`,
                  color: activeIndex === index ? activeTextColor : textColor,
                  fontSize: showLabels ? `${fontSize}px` : `${fontSize + 4}px`,
                  fontWeight,
                  letterSpacing,
                  fontFamily: '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif',
                  cursor: 'pointer',
                  transform: getItemTransform(index),
                  transformOrigin: '0px 0px',
                  transition: 'all 300ms ease-out',
                  display: 'flex',
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  gap: '2px',
                  padding: '0.5rem',
                  textAlign: 'center',
                  pointerEvents: isOpen ? 'auto' : 'none',
                  boxShadow: '0 1px 3px rgba(0,0,0,0.06)',
                  willChange: 'transform, opacity',
                  ...itemTransition
                }}
                onMouseEnter={(e) => {
                  if (activeIndex !== index) {
                    e.currentTarget.style.transform = getItemTransform(index) + ' scale(1.1)';
                    e.currentTarget.style.backgroundColor = activeItemColor;
                    e.currentTarget.style.color = activeTextColor;
                  }
                }}
                onMouseLeave={(e) => {
                  if (activeIndex !== index) {
                    e.currentTarget.style.transform = getItemTransform(index);
                    e.currentTarget.style.backgroundColor = itemBackgroundColor;
                    e.currentTarget.style.color = textColor;
                  }
                }}
              >
                {showLabels ? (
                  <span style={{
                    fontSize: '0.75em',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    maxWidth: '100%'
                  }}>
                    {item}
                  </span>
                ) : (
                  <span>{item.charAt(0)}</span>
                )}
              </button>
            );
          })}
        </div>
      </div>

      <style>{`
        @keyframes rotateCircle {
          from { transform: translate(-50%, -50%) rotate(0deg); }
          to { transform: translate(-50%, -50%) rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

