        "displayName": "Dock Position (Desktop)",
        "defaultValue": "right",
        "options": ["left", "right", "top", "bottom", "top-left", "top-right", "bottom-left", "bottom-right"],
        "group": "Content"
      },
      "dockPositionMobile": {
        "dataType": "select",
        "displayName": "Dock Position (Mobile)",
        "defaultValue": "bottom",
        "options": ["left", "right", "top", "bottom", "bottom-left", "bottom-right"],
        "group": "Content"
      },
      "radius": {
        "dataType": "select",
        "displayName": "Circle Radius",
        "defaultValue": "180",
        "options": ["120", "150", "180", "220", "260"],
        "group": "Content"
      },
      "transitionMode": {
        "dataType": "select",
        "displayName": "Item Transition",
        "defaultValue": "stagger",
        "options": ["stagger", "fade", "wave", "expand"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#F8F9FA",
        "group": "Colors"
      },
      "menuBackgroundColor": {
        "dataType": "color",
        "displayName": "Menu Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "itemBackgroundColor": {
        "dataType": "color",
        "displayName": "Item Background Color",
        "defaultValue": "#495057",
        "group": "Colors"
      },
      "itemHoverColor": {
        "dataType": "color",
        "displayName": "Item Hover Color",
        "defaultValue": "#212529",
        "group": "Colors"
      },
      "iconColor": {
        "dataType": "color",
        "displayName": "Icon Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
