          dasharray: '40 121', dashoffset: isOpen ? '-68px' : '0' },
        middle: { d: "m 70,50 h -40", dasharray: '40 40', dashoffset: '0' },
        bottom: { d: "m 30,67 h 40 c 0,0 8.5,0.149796 8.5,-8.5 0,-8.649796 -8.5,-8.5 -8.5,-8.5 h -20 v 20",
