          transform: 'scaleY(1)', opacity: 1,
          transition: prefersReducedMotion ? 'none' : 'all 300ms ease',
          pointerEvents: 'none'
        } : {
          content: '""', position: 'absolute', top: 0, left: 0,
          width: '100%', height: '100%',
          borderTop: `2px solid ${accentColor}`,
