function Component({ config = {} }) {
  const layoutPreset = config?.layoutPreset || 'horizontal-top-rail';
  const visualStyle = config?.visualStyle || 'bold-contrast';
  const showPercentage = config?.showPercentage !== false;
  const showSectionDots = config?.showSectionDots !== false;
  const sectionCount = parseInt(config?.sectionCount || '5');
  const animationIntensity = config?.animationIntensity || 'medium';
  const enableMorphing = config?.enableMorphing !== false;
  const enableGlitch = config?.enableGlitch === true;
  const numberSize = config?.numberSize || 'large';
  const fontStyle = config?.fontStyle || 'mono';

  const [scrollProgress, setScrollProgress] = React.useState(0);
  const [activeSection, setActiveSection] = React.useState(0);
  const [morphShape, setMorphShape] = React.useState(0); // 0=circle, 1=square, 2=triangle
  const [glitchActive, setGlitchActive] = React.useState(false);

  const containerRef = React.useRef(null);
  const sectionRefs = React.useRef([]);

  // Visual Style Presets
  const styles = {
    'bold-contrast': {
      primary: '#000000',
      accent: '#FFFFFF',
      background: '#FFFFFF',
      highlight: '#FF0000'
    },
    'neon-electric': {
      primary: '#00FF00',
      accent: '#FF00FF',
      background: '#000000',
      highlight: '#00FFFF'
    },
    'brutalist-mono': {
      primary: '#000000',
      accent: '#000000',
      background: '#F5F5F5',
      highlight: '#000000'
    },
    'minimal-refined': {
      primary: '#1A1A1A',
      accent: '#E5E5E5',
      background: '#FAFAFA',
      highlight: '#666666'
    },
    'glitch-tech': {
      primary: '#0A0A0A',
      accent: '#00FF41',
      background: '#0A0A0A',
      highlight: '#FF0080'
    }
  };

  const currentStyle = styles[visualStyle] || styles['bold-contrast'];
  const primaryColor = config?.primaryColor || currentStyle.primary;
  const accentColor = config?.accentColor || currentStyle.accent;
  const backgroundColor = config?.backgroundColor || currentStyle.background;

  // Animation timing based on intensity
  const timings = {
    'subtle': { duration: 600, easing: 'ease-out' },
    'medium': { duration: 400, easing: 'cubic-bezier(0.4, 0, 0.2, 1)' },
    'bold': { duration: 300, easing: 'cubic-bezier(0.68, -0.55, 0.265, 1.55)' },
    'extreme': { duration: 200, easing: 'cubic-bezier(0.87, -0.41, 0.19, 1.44)' }
  };

  const timing = timings[animationIntensity] || timings['medium'];

  // Number sizes
  const numberSizes = {
    'medium': '32px',
    'large': '48px',
    'xlarge': '64px',
    'oversized': '96px'
  };

  // Font families
  const fontFamilies = {
    'mono': "'JetBrains Mono', 'Courier New', monospace",
    'sans': "system-ui, -apple-system, sans-serif",
    'display': "'Space Grotesk', system-ui, sans-serif"
  };

  // Calculate scroll progress
  React.useEffect(() => {
    const updateProgress = () => {
      if (!containerRef.current) return;

      const container = containerRef.current;
      const scrollTop = container.scrollTop;
      const scrollHeight = container.scrollHeight;
      const clientHeight = container.clientHeight;
      const scrollableDistance = scrollHeight - clientHeight;

      if (scrollableDistance <= 0) {
        setScrollProgress(0);
        return;
      }

      const progress = (scrollTop / scrollableDistance) * 100;
      setScrollProgress(Math.min(100, Math.max(0, progress)));

      // Shape morphing based on scroll
      if (enableMorphing) {
        if (progress < 33) setMorphShape(0); // Circle
        else if (progress < 66) setMorphShape(1); // Square
        else setMorphShape(2); // Triangle
      }
    };

    const container = containerRef.current;
    if (!container) return;

    container.addEventListener('scroll', updateProgress, { passive: true });
    updateProgress();

    return () => {
      container.removeEventListener('scroll', updateProgress);
    };
  }, [enableMorphing]);

  // Intersection Observer for sections
  React.useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const observers = sectionRefs.current.map((section, index) => {
      if (!section) return null;

      const observer = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const prevSection = activeSection;
              setActiveSection(index);

              // Trigger glitch on section change
              if (enableGlitch && prevSection !== index) {
                setGlitchActive(true);
                setTimeout(() => setGlitchActive(false), 100);
              }
            }
          });
        },
        { threshold: 0.5, root: container }
      );

      observer.observe(section);
      return observer;
    });

    return () => {
      observers.forEach(observer => observer?.disconnect());
    };
  }, [sectionCount, activeSection, enableGlitch]);

  // Scroll to section
  const scrollToSection = (index) => {
    const section = sectionRefs.current[index];
    if (section && containerRef.current) {
      const container = containerRef.current;
      const sectionTop = section.offsetTop;
      container.scrollTo({ top: sectionTop, behavior: 'smooth' });
    }
  };

  // Respect prefers-reduced-motion
  const prefersReducedMotion = React.useMemo(() => {
    return window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  }, []);

  // Render different layouts
  const renderIndicator = () => {
    switch (layoutPreset) {
      case 'horizontal-top-rail':
        return (
          <div style={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            height: '4px',
            backgroundColor: accentColor,
            zIndex: 9999,
            opacity: 0.3
          }}>
            <div style={{
              height: '100%',
              width: `${scrollProgress}%`,
              backgroundColor: primaryColor,
              transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms ${timing.easing}`,
              position: 'relative'
            }}>
              {/* Kinetic number at progress point */}
              {showPercentage && (
                <div style={{
                  position: 'absolute',
                  right: '-20px',
                  top: '10px',
                  fontSize: '14px',
                  fontWeight: '700',
                  fontFamily: fontFamilies[fontStyle],
                  color: primaryColor,
                  letterSpacing: '0.05em',
                  transform: glitchActive ? 'translateX(2px)' : 'translateX(0)',
                  transition: prefersReducedMotion ? 'none' : `transform 100ms`
                }}>
                  {Math.round(scrollProgress)}%
                </div>
              )}
            </div>
            {/* Section dots */}
            {showSectionDots && (
              <div style={{
                position: 'absolute',
                top: '-6px',
                left: 0,
                right: 0,
                display: 'flex',
                justifyContent: 'space-between',
                padding: '0 20px'
              }}>
                {Array.from({ length: sectionCount }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => scrollToSection(i)}
                    style={{
                      width: '16px',
                      height: '16px',
                      borderRadius: activeSection === i ? '0%' : '50%',
                      backgroundColor: activeSection === i ? primaryColor : accentColor,
                      border: `2px solid ${primaryColor}`,
                      cursor: 'pointer',
                      transition: prefersReducedMotion ? 'none' : `all ${timing.duration}ms ${timing.easing}`,
                      transform: activeSection === i ? 'scale(1.2) rotate(45deg)' : 'scale(1) rotate(0deg)'
                    }}
                    aria-label={`Section ${i + 1}`}
                  />
                ))}
              </div>
            )}
          </div>
        );

      case 'horizontal-bottom-rail':
        return (
          <div style={{
            position: 'fixed',
            bottom: 0,
            left: 0,
            right: 0,
            height: '8px',
            backgroundColor: backgroundColor,
            borderTop: `1px solid ${accentColor}`,
            zIndex: 9999
          }}>
            <div style={{
              height: '100%',
              width: `${scrollProgress}%`,
              background: `linear-gradient(90deg, ${primaryColor} 0%, ${currentStyle.highlight} 100%)`,
              transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms ${timing.easing}`,
              position: 'relative'
            }}>
              {showPercentage && (
                <div style={{
                  position: 'absolute',
                  right: '10px',
                  top: '50%',
                  transform: 'translateY(-50%)',
                  fontSize: numberSizes[numberSize],
                  fontWeight: '900',
                  fontFamily: fontFamilies[fontStyle],
                  color: backgroundColor,
                  mixBlendMode: 'difference',
                  letterSpacing: '-0.02em',
                  lineHeight: '1'
                }}>
