              <div style={{
                display: 'flex',
                flexDirection: 'column',
                gap: '12px'
              }}>
                {Array.from({ length: sectionCount }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => scrollToSection(i)}
                    style={{
                      width: '8px',
                      height: activeSection === i ? '30px' : '8px',
                      backgroundColor: activeSection === i ? accentColor : 'transparent',
                      border: `1px solid ${accentColor}`,
                      cursor: 'pointer',
                      transition: prefersReducedMotion ? 'none' : `all ${timing.duration}ms ${timing.easing}`
                    }}
                    aria-label={`Section ${i + 1}`}
                  />
                ))}
              </div>
            )}
          </div>
        );

      case 'corner-morphing-shape':
        return (
          <div style={{
            position: 'fixed',
            bottom: '30px',
            right: '30px',
            zIndex: 9999
          }}>
            <div style={{
              width: '100px',
              height: '100px',
              position: 'relative',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center'
            }}>
              {/* Morphing shape background */}
              <div style={{
                position: 'absolute',
                inset: 0,
                backgroundColor: primaryColor,
                borderRadius: morphShape === 0 ? '50%' : morphShape === 1 ? '4px' : '0%',
                transform: morphShape === 2 ? 'rotate(30deg)' : 'rotate(0deg)',
                clipPath: morphShape === 2 ? 'polygon(50% 0%, 0% 100%, 100% 100%)' : 'none',
                transition: prefersReducedMotion ? 'none' : `all ${timing.duration * 2}ms ${timing.easing}`
              }} />

              {/* Progress ring */}
              <svg width="100" height="100" style={{ position: 'absolute', transform: 'rotate(-90deg)' }}>
                <circle
                  cx="50"
                  cy="50"
                  r="45"
                  fill="none"
                  stroke={accentColor}
                  strokeWidth="2"
                  opacity="0.3"
                />
                <circle
                  cx="50"
                  cy="50"
                  r="45"
                  fill="none"
                  stroke={accentColor}
                  strokeWidth="4"
                  strokeDasharray={`${2 * Math.PI * 45}`}
                  strokeDashoffset={`${2 * Math.PI * 45 * (1 - scrollProgress / 100)}`}
                  strokeLinecap="round"
                  style={{
                    transition: prefersReducedMotion ? 'none' : `stroke-dashoffset ${timing.duration}ms linear`
                  }}
                />
              </svg>

              {/* Number */}
              {showPercentage && (
                <div style={{
                  fontSize: '24px',
                  fontWeight: '900',
                  fontFamily: fontFamilies[fontStyle],
                  color: accentColor,
                  letterSpacing: '-0.02em',
                  zIndex: 1
                }}>
                  {Math.round(scrollProgress)}
                </div>
              )}
            </div>
          </div>
        );

      case 'floating-kinetic-number':
        return (
          <div style={{
            position: 'fixed',
            top: '50%',
            right: '40px',
            transform: 'translateY(-50%)',
            zIndex: 9999,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'flex-end',
            gap: '20px'
          }}>
            {/* Giant percentage */}
            {showPercentage && (
              <div style={{
                fontSize: numberSizes[numberSize],
                fontWeight: '900',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                letterSpacing: '-0.05em',
                lineHeight: '0.9',
                textAlign: 'right',
                display: 'flex',
                flexDirection: 'column'
              }}>
                <span style={{
                  transform: `translateY(${glitchActive ? '2px' : '0px'})`,
                  transition: 'transform 100ms'
                }}>
                  {String(Math.round(scrollProgress)).padStart(3, '0')}
                </span>
                <span style={{
                  fontSize: '16px',
                  fontWeight: '400',
                  letterSpacing: '0.2em',
                  marginTop: '8px'
                }}>
                  PERCENT
                </span>
              </div>
            )}

            {/* Section dots - vertical */}
            {showSectionDots && (
              <div style={{
                display: 'flex',
                flexDirection: 'column',
                gap: '16px',
                alignItems: 'flex-end'
              }}>
                {Array.from({ length: sectionCount }).map((_, i) => (
                  <button
                    key={i}
                    onClick={() => scrollToSection(i)}
                    style={{
                      width: activeSection === i ? '60px' : '30px',
                      height: '3px',
                      backgroundColor: primaryColor,
                      border: 'none',
                      cursor: 'pointer',
                      transition: prefersReducedMotion ? 'none' : `all ${timing.duration}ms ${timing.easing}`,
                      position: 'relative'
                    }}
                    aria-label={`Section ${i + 1}`}
                  >
                    {activeSection === i && (
                      <span style={{
                        position: 'absolute',
                        right: '70px',
                        top: '50%',
                        transform: 'translateY(-50%)',
                        fontSize: '11px',
                        fontWeight: '700',
                        fontFamily: fontFamilies[fontStyle],
                        letterSpacing: '0.1em',
                        color: primaryColor,
                        whiteSpace: 'nowrap'
                      }}>
                        SECTION {String(i + 1).padStart(2, '0')}
                      </span>
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>
        );

      case 'split-screen-bars':
        return (
          <>
            {/* Left bar */}
            <div style={{
              position: 'fixed',
              left: 0,
              top: 0,
              bottom: 0,
              width: '12px',
              backgroundColor: primaryColor,
              zIndex: 9999
            }}>
              <div style={{
                width: '100%',
                height: `${scrollProgress}%`,
                backgroundColor: currentStyle.highlight,
                transition: prefersReducedMotion ? 'none' : `height ${timing.duration}ms ${timing.easing}`
              }} />
            </div>

            {/* Right bar */}
            <div style={{
              position: 'fixed',
              right: 0,
              top: 0,
              bottom: 0,
              width: '12px',
              backgroundColor: primaryColor,
              zIndex: 9999
            }}>
              <div style={{
                width: '100%',
                height: `${100 - scrollProgress}%`,
                backgroundColor: accentColor,
                transition: prefersReducedMotion ? 'none' : `height ${timing.duration}ms ${timing.easing}`
              }} />
            </div>

            {/* Center floating number */}
            {showPercentage && (
              <div style={{
                position: 'fixed',
                top: '50%',
                left: '50%',
                transform: 'translate(-50%, -50%)',
                fontSize: numberSizes[numberSize],
                fontWeight: '900',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                letterSpacing: '-0.05em',
                zIndex: 10000,
                pointerEvents: 'none',
                mixBlendMode: 'difference'
              }}>
                {String(Math.round(scrollProgress)).padStart(2, '0')}
              </div>
            )}
          </>
        );

      case 'geometric-corners':
        return (
          <>
            {/* Top-left corner */}
            <div style={{
              position: 'fixed',
              top: 0,
              left: 0,
              width: `${scrollProgress * 2}px`,
              height: '4px',
              backgroundColor: primaryColor,
              zIndex: 9999,
              maxWidth: '200px',
              transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms ${timing.easing}`
            }} />
            <div style={{
              position: 'fixed',
              top: 0,
              left: 0,
              width: '4px',
              height: `${scrollProgress * 2}px`,
              backgroundColor: primaryColor,
              zIndex: 9999,
              maxHeight: '200px',
              transition: prefersReducedMotion ? 'none' : `height ${timing.duration}ms ${timing.easing}`
            }} />

            {/* Bottom-right corner */}
            <div style={{
              position: 'fixed',
              bottom: 0,
              right: 0,
              width: `${scrollProgress * 2}px`,
              height: '4px',
              backgroundColor: currentStyle.highlight,
              zIndex: 9999,
              maxWidth: '200px',
              transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms ${timing.easing}`
            }} />
            <div style={{
              position: 'fixed',
              bottom: 0,
              right: 0,
              width: '4px',
              height: `${scrollProgress * 2}px`,
              backgroundColor: currentStyle.highlight,
              zIndex: 9999,
              maxHeight: '200px',
              transition: prefersReducedMotion ? 'none' : `height ${timing.duration}ms ${timing.easing}`
            }} />

            {/* Number in corner */}
            {showPercentage && (
              <div style={{
                position: 'fixed',
                top: '20px',
                right: '20px',
                fontSize: numberSizes[numberSize],
                fontWeight: '900',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                letterSpacing: '-0.05em',
                zIndex: 10000
              }}>
                {String(Math.round(scrollProgress)).padStart(2, '0')}
              </div>
            )}
          </>
        );

      case 'brutalist-bar':
        return (
          <div style={{
            position: 'fixed',
            bottom: 0,
            left: 0,
            right: 0,
