              <div style={{
                height: '100%',
                width: `${scrollProgress}%`,
                backgroundColor: currentStyle.highlight,
                transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms ${timing.easing}`,
                border: `2px solid ${backgroundColor}`
              }} />
            </div>

            {/* Percentage */}
            {showPercentage && (
              <div style={{
                marginLeft: '30px',
                fontSize: '32px',
                fontWeight: '900',
                fontFamily: fontFamilies[fontStyle],
                color: accentColor,
                letterSpacing: '0em',
                minWidth: '100px',
                textAlign: 'right'
              }}>
                {String(Math.round(scrollProgress)).padStart(3, '0')}%
              </div>
            )}
          </div>
        );

      case 'minimal-line':
        return (
          <div style={{
            position: 'fixed',
            top: '50%',
            left: '50%',
            transform: `translate(-50%, -50%) rotate(-90deg)`,
            zIndex: 9999,
            width: '80vh',
            height: '1px',
            backgroundColor: accentColor,
            opacity: 0.3
          }}>
            <div style={{
              height: '100%',
              width: `${scrollProgress}%`,
              backgroundColor: primaryColor,
              transition: prefersReducedMotion ? 'none' : `width ${timing.duration}ms linear`,
              position: 'relative'
            }}>
              {showPercentage && (
                <div style={{
                  position: 'absolute',
                  right: '-40px',
                  top: '50%',
                  transform: 'translateY(-50%) rotate(90deg)',
