  // Section titles
  const sectionTitles = [
    { title: "BOLD", subtitle: "Make it count" },
    { title: "KINETIC", subtitle: "Always moving" },
    { title: "EXPERIMENTAL", subtitle: "Push boundaries" },
    { title: "AWARD-WINNING", subtitle: "Stand out" },
    { title: "EDGY", subtitle: "Break the rules" },
    { title: "DYNAMIC", subtitle: "Never static" },
    { title: "CONTEMPORARY", subtitle: "Now, not then" },
    { title: "IMPACTFUL", subtitle: "Impossible to ignore" }
  ];

  return (
    <div style={{ position: 'relative', width: '100%', height: '100vh' }}>
      {/* Scrollable container */}
      <div
        ref={containerRef}
        className="award-scroll-indicator"
        style={{
          width: '100%',
          height: '100vh',
          overflow: 'auto',
          backgroundColor: backgroundColor
        }}
      >
        {/* Hero */}
        <div style={{
          minHeight: '100vh',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          padding: '60px 20px',
          textAlign: 'center'
        }}>
          <div style={{
            fontSize: '12px',
            fontWeight: '700',
            fontFamily: fontFamilies[fontStyle],
            color: primaryColor,
            letterSpacing: '0.3em',
            marginBottom: '30px'
          }}>
            AWARD-WINNING SCROLL INDICATORS
          </div>
          <h1 style={{
            fontSize: '72px',
            fontWeight: '900',
            fontFamily: fontFamilies[fontStyle],
            color: primaryColor,
            marginBottom: '20px',
            letterSpacing: '-0.03em',
            lineHeight: '1',
            maxWidth: '900px'
          }}>
            NO MORE BORING CIRCLES
          </h1>
          <p style={{
            fontSize: '20px',
            fontWeight: '400',
            color: primaryColor,
            opacity: 0.7,
            maxWidth: '600px',
            lineHeight: '1.6'
          }}>
            10 edgy layouts inspired by Awwwards. Horizontal rails, vertical indicators, 
            morphing shapes, kinetic numbers, brutalist bars, and experimental designs.
          </p>
        </div>

        {/* Content Sections */}
        {Array.from({ length: sectionCount }).map((_, index) => (
          <div
            key={index}
            ref={el => sectionRefs.current[index] = el}
            style={{
              minHeight: '100vh',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              justifyContent: 'center',
              padding: '100px 20px',
              backgroundColor: index % 2 === 0 ? backgroundColor : (primaryColor === '#000000' ? '#0A0A0A' : '#FAFAFA'),
              transition: prefersReducedMotion ? 'none' : 'background-color 500ms ease-out'
            }}
          >
            <div style={{
              maxWidth: '800px',
              width: '100%'
            }}>
              <div style={{
                fontSize: '14px',
                fontWeight: '700',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                letterSpacing: '0.3em',
                marginBottom: '30px',
                opacity: activeSection === index ? 1 : 0.5,
                transition: 'opacity 300ms ease-out'
              }}>
                {String(index + 1).padStart(2, '0')}
              </div>

              <h2 style={{
                fontSize: '64px',
                fontWeight: '900',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                marginBottom: '16px',
                letterSpacing: '-0.02em',
                lineHeight: '1'
              }}>
                {sectionTitles[index].title}
              </h2>

              <div style={{
                fontSize: '24px',
                fontWeight: '400',
                fontFamily: fontFamilies[fontStyle],
                color: primaryColor,
                opacity: 0.6,
                marginBottom: '40px'
              }}>
                {sectionTitles[index].subtitle}
              </div>

              <p style={{
                fontSize: '18px',
                fontWeight: '400',
                color: primaryColor,
                opacity: 0.8,
                lineHeight: '1.7',
                marginBottom: '20px'
              }}>
                This is award-winning scroll indicator design. No more boring circles stuck 
                in corners. We're talking horizontal rails, vertical bars, morphing geometric 
                shapes, oversized kinetic numbers, brutalist aesthetics.
              </p>

              <p style={{
                fontSize: '18px',
                fontWeight: '400',
                color: primaryColor,
                opacity: 0.8,
                lineHeight: '1.7'
              }}>
                Choose from 10 experimental layouts. Each one pushes boundaries. Each one 
                makes a statement. This is how modern websites track scroll progress.
              </p>
            </div>
          </div>
        ))}
      </div>

      {/* Render the selected indicator layout */}
      {renderIndicator()}

      {/* Glitch overlay */}
      {enableGlitch && glitchActive && (
        <div style={{
          position: 'fixed',
          inset: 0,
          backgroundColor: currentStyle.highlight,
          opacity: 0.1,
          pointerEvents: 'none',
          zIndex: 10001,
          animation: 'glitchFlash 100ms'
        }} />
      )}

      <style>{`
        @keyframes glitchFlash {
          0%, 100% { opacity: 0; }
          50% { opacity: 0.2; }
        }
      `}</style>
    </div>
  );
}

