      },
      "grainAmount": {
        "dataType": "select",
        "displayName": "Grain Amount",
        "defaultValue": "medium",
        "options": ["subtle", "medium", "heavy"],
        "group": "Hover Effects"
      },
      "glitchIntensity": {
        "dataType": "select",
        "displayName": "Glitch Intensity",
        "defaultValue": "medium",
        "options": ["subtle", "medium", "extreme"],
        "group": "Hover Effects"
      },
      "charAnimationSpeed": {
        "dataType": "select",
        "displayName": "Character Animation Speed",
        "defaultValue": "medium",
        "options": ["slow", "medium", "fast"],
        "group": "Hover Effects"
      },
      "baseFontSize": {
        "dataType": "select",
        "displayName": "Base Font Size",
        "defaultValue": "20vw",
        "options": ["5vw", "8vw", "10vw", "12vw", "15vw", "18vw", "20vw", "22vw", "25vw", "28vw", "30vw"],
        "group": "Typography",
        "description": "Full range: 5vw (subtle) to 30vw (overwhelming)"
      },
      "defaultFontFamily": {
        "dataType": "select",
        "displayName": "Default Font Family",
        "defaultValue": "sans",
        "options": ["sans", "serif", "mono"],
        "group": "Typography"
      },
      "minFontWeight": {
        "dataType": "select",
        "displayName": "Minimum Font Weight",
        "defaultValue": "300",
        "options": ["300", "400"],
        "group": "Typography"
      },
      "maxFontWeight": {
        "dataType": "select",
        "displayName": "Maximum Font Weight",
        "defaultValue": "500",
        "options": ["400", "500"],
        "group": "Typography"
      },
      "fontWeightTransitionDuration": {
        "dataType": "select",
        "displayName": "Font Weight Transition (ms)",
        "defaultValue": "400",
        "options": ["200", "300", "400", "500", "600", "800"],
        "group": "Typography"
      },
      "letterSpacing": {
        "dataType": "select",
        "displayName": "Letter Spacing",
        "defaultValue": "0.1em",
        "options": ["0em", "0.025em", "0.05em", "0.075em", "0.1em", "0.125em", "0.15em", "0.2em"],
        "group": "Typography"
      },
      "descriptorFontSize": {
        "dataType": "number",
        "displayName": "Descriptor Font Size (px)",
        "defaultValue": 14,
        "group": "Typography"
      },
      "staggerDelay": {
        "dataType": "select",
        "displayName": "Entrance Stagger Delay (ms)",
        "defaultValue": "150",
        "options": ["100", "150", "200", "250"],
        "group": "Animation"
      },
      "magneticRadius": {
        "dataType": "select",
        "displayName": "Magnetic Field Radius (px)",
        "defaultValue": "200",
        "options": ["150", "200", "250", "300"],
        "group": "Animation"
      },
      "magneticStrength": {
        "dataType": "select",
        "displayName": "Magnetic Strength",
        "defaultValue": "0.15",
        "options": ["0.1", "0.15", "0.2", "0.25", "0.3"],
        "group": "Animation"
      },
      "explosionDuration": {
        "dataType": "select",
        "displayName": "Explosion Duration (ms)",
        "defaultValue": "800",
        "options": ["600", "800", "1000", "1200"],
        "group": "Animation"
      },
      "backgroundColor": {
        "dataType": "color",
        "displayName": "Background Color",
        "defaultValue": "#FFFFFF",
        "group": "Colors"
      },
      "secondaryBgColor": {
        "dataType": "color",
        "displayName": "Secondary Background",
        "defaultValue": "#FAFAFA",
        "group": "Colors"
      },
      "textColor": {
        "dataType": "color",
        "displayName": "Text Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      },
      "descriptorColor": {
        "dataType": "color",
        "displayName": "Descriptor Color",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "hoverColor": {
        "dataType": "color",
        "displayName": "Hover State Color",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "activeColor": {
        "dataType": "color",
        "displayName": "Active State Color",
        "defaultValue": "#27272A",
        "group": "Colors"
      },
      "inactiveColor": {
        "dataType": "color",
        "displayName": "Inactive State Color",
        "defaultValue": "#A1A1AA",
        "group": "Colors"
      },
      "glowColor": {
        "dataType": "color",
        "displayName": "Glow Effect Color",
        "defaultValue": "#3F3F46",
        "group": "Colors"
      },
      "hamburgerColor": {
        "dataType": "color",
        "displayName": "Hamburger Button Color",
        "defaultValue": "#18181B",
        "group": "Colors"
      }
    },
    "layout": {
      "resizeDirection": "horizontalAndVertical",
      "contentResizeDirection": "vertical"
    }
  }
};

function Component({ config = {} }) {
  const [isOpen, setIsOpen] = React.useState(false);
  const [hoveredIndex, setHoveredIndex] = React.useState(null);
  const [activeIndex, setActiveIndex] = React.useState(null);
  const [mousePos, setMousePos] = React.useState({ x: 0, y: 0 });
  const [animatedIndices, setAnimatedIndices] = React.useState(new Set());
  const [hasAnimated, setHasAnimated] = React.useState(false);
  const [exploding, setExploding] = React.useState(null);
  const [scrollY, setScrollY] = React.useState(0);
  const [charAnimStates, setCharAnimStates] = React.useState({});
  const [glitchOffset, setGlitchOffset] = React.useState({ x: 0, y: 0 });
  const containerRef = React.useRef(null);
  const itemRefs = React.useRef([]);

  // Extract config with safe defaults
  const menuItems = (config?.menuItems || "HOME,WORK,ABOUT,SERVICES,CONTACT").split(',').map(item => item.trim());
  const menuDescriptors = (config?.menuDescriptors || "Start Here,Our Portfolio,Who We Are,What We Do,Get In Touch").split(',').map(item => item.trim());
  const enableMagneticDistortion = config?.enableMagneticDistortion !== false;
  const enableVariableFontWeight = config?.enableVariableFontWeight !== false;
  const enableParallax = config?.enableParallax !== false;
  const enableInactiveBlur = config?.enableInactiveBlur !== false;
  const showHamburger = config?.showHamburger !== false;
  const triggerMode = config?.triggerMode || "scroll";

  const layoutMode = config?.layoutMode || "horizontal";
  const itemSpacing = config?.itemSpacing || "2vh";

  const hoverEffect = config?.hoverEffect || "glow";
  const hoverFontFamily = config?.hoverFontFamily || "serif";
  const glowIntensity = config?.glowIntensity || "medium";
  const shadowDepth = config?.shadowDepth || "medium";
  const underlineThickness = config?.underlineThickness || "2";
  const scalePulseAmount = parseFloat(config?.scalePulseAmount || "1.02");
  const noiseIntensity = config?.noiseIntensity || "medium";
  const grainAmount = config?.grainAmount || "medium";
  const glitchIntensity = config?.glitchIntensity || "medium";
  const charAnimationSpeed = config?.charAnimationSpeed || "medium";

  const baseFontSize = config?.baseFontSize || "20vw";
  const defaultFontFamily = config?.defaultFontFamily || "sans";
  const minFontWeight = config?.minFontWeight || "300";
  const maxFontWeight = config?.maxFontWeight || "500";
  const fontWeightTransitionDuration = parseInt(config?.fontWeightTransitionDuration || "400");
  const letterSpacing = config?.letterSpacing || "0.1em";
  const descriptorFontSize = config?.descriptorFontSize || 14;

  const staggerDelay = parseInt(config?.staggerDelay || "150");
  const magneticRadius = parseInt(config?.magneticRadius || "200");
  const magneticStrength = parseFloat(config?.magneticStrength || "0.15");
  const explosionDuration = parseInt(config?.explosionDuration || "800");

  const backgroundColor = config?.backgroundColor || "#FFFFFF";
  const secondaryBgColor = config?.secondaryBgColor || "#FAFAFA";
  const textColor = config?.textColor || "#18181B";
  const descriptorColor = config?.descriptorColor || "#3F3F46";
  const hoverColor = config?.hoverColor || "#3F3F46";
  const activeColor = config?.activeColor || "#27272A";
  const inactiveColor = config?.inactiveColor || "#A1A1AA";
  const glowColor = config?.glowColor || "#3F3F46";
  const hamburgerColor = config?.hamburgerColor || "#18181B";

  // Detect reduced motion
  const prefersReducedMotion = typeof window !== 'undefined' 
    ? window.matchMedia('(prefers-reduced-motion: reduce)').matches 
    : false;

  // Glitch effect animation
  React.useEffect(() => {
    if (hoveredIndex === null || (hoverEffect !== 'glitch' && hoverEffect !== 'multi')) {
      setGlitchOffset({ x: 0, y: 0 });
      return;
    }

    const intensityMap = {
      subtle: 2,
      medium: 5,
      extreme: 10
    };
    const maxOffset = intensityMap[glitchIntensity] || 5;

    const interval = setInterval(() => {
      if (Math.random() > 0.7) { // 30% chance of glitch
        setGlitchOffset({
          x: (Math.random() - 0.5) * maxOffset,
          y: (Math.random() - 0.5) * maxOffset
        });
      } else {
        setGlitchOffset({ x: 0, y: 0 });
      }
    }, 100);

    return () => clearInterval(interval);
  }, [hoveredIndex, hoverEffect, glitchIntensity]);

  // Get font family stack
  const getFontFamily = (isHovered) => {
    const shouldSwap = isHovered && (hoverEffect === 'font-swap' || hoverEffect === 'multi');
    const targetFamily = shouldSwap ? hoverFontFamily : defaultFontFamily;

    const familyMap = {
      'sans': '-apple-system, BlinkMacSystemFont, "Inter", "SF Pro Display", "Segoe UI", Roboto, sans-serif',
      'serif': 'Georgia, "Times New Roman", Times, serif',
      'mono': '"SF Mono", Monaco, "Cascadia Code", "Roboto Mono", Consolas, "Courier New", monospace',
      'sans-condensed': '"SF Pro Condensed", "Helvetica Neue Condensed", "Arial Narrow", sans-serif'
    };

    return familyMap[targetFamily] || familyMap.sans;
  };

  // Get character animation speed multiplier
  const getCharAnimSpeed = () => {
    const speedMap = {
      slow: 1.5,
      medium: 1.0,
      fast: 0.6
    };
    return speedMap[charAnimationSpeed] || 1.0;
  };

  // Get noise filter intensity
  const getNoiseFilter = () => {
    if (hoverEffect !== 'noise' && hoverEffect !== 'multi') return '';

    const intensityMap = {
      subtle: 0.3,
      medium: 0.5,
      intense: 0.8
    };

    return `url(#noise-${intensityMap[noiseIntensity] || 0.5})`;
  };

  // Get grain filter
  const getGrainFilter = (isHovered) => {
    if (!isHovered || (hoverEffect !== 'grain' && hoverEffect !== 'multi')) return 'none';

    const amountMap = {
      subtle: 'grayscale(15%) contrast(120%)',
      medium: 'grayscale(30%) contrast(150%)',
      heavy: 'grayscale(50%) contrast(180%)'
    };

    return amountMap[grainAmount] || amountMap.medium;
  };

  // Get glitch text shadow
  const getGlitchShadow = (isHovered) => {
    if (!isHovered || (hoverEffect !== 'glitch' && hoverEffect !== 'multi')) return 'none';

    return `${glitchOffset.x}px ${glitchOffset.y}px 0 rgba(255, 0, 0, 0.7), ${-glitchOffset.x}px ${-glitchOffset.y}px 0 rgba(0, 255, 255, 0.7)`;
  };

  // Get glow effect values
  const getGlowShadow = () => {
    if (hoverEffect !== 'glow' && hoverEffect !== 'multi') return 'none';

    const intensityMap = {
      subtle: '0 0 10px',
      medium: '0 0 20px',
      intense: '0 0 40px'
    };

    const glowSize = intensityMap[glowIntensity] || intensityMap.medium;
    return `${glowSize} ${glowColor}, ${glowSize} ${glowColor}`;
  };

  // Get shadow effect values
  const getDropShadow = () => {
    if (hoverEffect !== 'shadow' && hoverEffect !== 'multi') return 'none';

    const depthMap = {
      subtle: '0 4px 8px rgba(0,0,0,0.06)',
      medium: '0 8px 16px rgba(0,0,0,0.08)',
      deep: '0 16px 32px rgba(0,0,0,0.12)'
    };

    return depthMap[shadowDepth] || depthMap.medium;
  };

  // Trigger character animations on hover
  React.useEffect(() => {
    if (hoveredIndex === null) {
      setCharAnimStates({});
      return;
    }

    const needsCharAnim = ['char-wave', 'char-rotate', 'char-stagger', 'char-explode', 'multi'].includes(hoverEffect);
    if (!needsCharAnim) return;

    const item = menuItems[hoveredIndex];
    const chars = item.split('');
    const speedMultiplier = getCharAnimSpeed();

    if (hoverEffect === 'char-stagger' || hoverEffect === 'multi') {
      chars.forEach((_, charIdx) => {
        setTimeout(() => {
          setCharAnimStates(prev => ({
            ...prev,
            [`${hoveredIndex}-${charIdx}`]: true
          }));
        }, charIdx * 50 * speedMultiplier);
      });
    } else {
      const newStates = {};
      chars.forEach((_, charIdx) => {
        newStates[`${hoveredIndex}-${charIdx}`] = true;
      });
      setCharAnimStates(newStates);
    }
  }, [hoveredIndex, hoverEffect, menuItems]);

  // Get character-level transform based on hover effect
  const getCharTransform = (itemIndex, charIndex, isHovered) => {
    if (!isHovered || prefersReducedMotion) return 'none';

    const isAnimated = charAnimStates[`${itemIndex}-${charIndex}`];
    const speedMultiplier = getCharAnimSpeed();

    switch(hoverEffect) {
      case 'char-wave':
      case 'multi':
        return `translateY(${Math.sin(charIndex * 0.5) * 20}px)`;

      case 'char-rotate':
        return isAnimated ? 'rotate(0deg)' : 'rotate(360deg)';

      case 'char-stagger':
        return isAnimated ? 'translateX(0)' : 'translateX(-20px)';

      case 'char-explode':
        const angle = (charIndex * 45) % 360;
        const distance = 30;
        const x = Math.cos(angle * Math.PI / 180) * distance;
        const y = Math.sin(angle * Math.PI / 180) * distance;
        return `translate(${x}px, ${y}px) rotate(${charIndex * 45}deg) scale(1.2)`;

      default:
        return 'none';
    }
  };

  // Get character opacity for stagger effect
  const getCharOpacity = (itemIndex, charIndex, isHovered) => {
    if (!isHovered || hoverEffect !== 'char-stagger') return 1;
    return charAnimStates[`${itemIndex}-${charIndex}`] ? 1 : 0;
  };

  // Mouse tracking
  React.useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  // Scroll tracking for parallax
  React.useEffect(() => {
    if (!enableParallax) return;

    const handleScroll = () => {
      setScrollY(window.scrollY);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [enableParallax]);

  // Intersection Observer for scroll trigger
  React.useEffect(() => {
    if (triggerMode === 'manual' || !isOpen) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            if (triggerMode === 'entrance' && hasAnimated) return;

            const itemIndex = itemRefs.current.indexOf(entry.target);
            if (itemIndex !== -1) {
              setTimeout(() => {
                setAnimatedIndices(prev => {
                  const newSet = new Set(prev);
                  newSet.add(itemIndex);
                  return newSet;
                });
              }, itemIndex * staggerDelay);
            }
          }
        });

        if (triggerMode === 'entrance') {
          setHasAnimated(true);
        }
      },
      { threshold: 0.3 }
    );

    itemRefs.current.forEach(ref => {
      if (ref) observer.observe(ref);
    });

    return () => observer.disconnect();
  }, [triggerMode, hasAnimated, staggerDelay, isOpen]);

  // Auto-trigger animations when menu opens
  React.useEffect(() => {
    if (isOpen && triggerMode === 'manual') {
      menuItems.forEach((_, idx) => {
        setTimeout(() => {
          setAnimatedIndices(prev => {
            const newSet = new Set(prev);
            newSet.add(idx);
            return newSet;
          });
        }, idx * staggerDelay);
      });
    }
  }, [isOpen, triggerMode, menuItems.length, staggerDelay]);

  // Calculate magnetic distortion for character
  const getMagneticOffset = (itemIndex, charIndex, charRect) => {
    if (!enableMagneticDistortion || hoveredIndex !== itemIndex || !charRect || prefersReducedMotion) {
      return { x: 0, y: 0 };
    }

    const charCenterX = charRect.left + charRect.width / 2;
    const charCenterY = charRect.top + charRect.height / 2;

    const distX = mousePos.x - charCenterX;
    const distY = mousePos.y - charCenterY;
    const distance = Math.sqrt(distX * distX + distY * distY);

    if (distance < magneticRadius && distance > 0) {
      const strength = (1 - distance / magneticRadius) * magneticStrength * 100;
      return {
        x: (distX / distance) * strength,
        y: (distY / distance) * strength
      };
    }

    return { x: 0, y: 0 };
  };

  // Handle item click
  const handleItemClick = (index, e) => {
    if (prefersReducedMotion) {
      console.log('Selected:', menuItems[index]);
      return;
    }

    const rect = e.currentTarget.getBoundingClientRect();
    const clickX = e.clientX - rect.left;
    const clickY = e.clientY - rect.top;

    setExploding({ index, x: clickX, y: clickY });
    setActiveIndex(index);

    setTimeout(() => {
      console.log('Selected:', menuItems[index]);
    }, explosionDuration);
  };

  // Get parallax offset
  const getParallaxOffset = (layerIndex) => {
    if (!enableParallax || prefersReducedMotion) return 0;

    const speeds = [0.3, 0.5, 0.7, 1.0];
    const speed = speeds[layerIndex % speeds.length];
    return scrollY * speed * 0.1;
  };

  // Get layout styles
  const getLayoutStyles = () => {
    switch(layoutMode) {
      case 'vertical':
        return {
          writingMode: 'vertical-rl',
          textOrientation: 'mixed',
          flexDirection: 'row',
          justifyContent: 'space-around',
          alignItems: 'center',
          gap: itemSpacing
        };
      case 'stacked':
        return {
          flexDirection: 'column',
          justifyContent: 'space-between',
          height: '100vh',
          padding: '10vh 8vw',
          gap: '0'
        };
      case 'grid':
        return {
          display: 'grid',
          gridTemplateColumns: 'repeat(2, 1fr)',
          gap: itemSpacing,
          padding: '8vh 8vw'
        };
      default: // horizontal
        return {
          flexDirection: 'column',
          justifyContent: 'center',
          gap: itemSpacing
        };
    }
  };

  return (
    <div 
      ref={containerRef}
      className="explosive-typographic-menu"
      style={{
        position: 'relative',
        width: '100%',
        minHeight: '100vh',
        backgroundColor: backgroundColor,
        overflow: 'hidden',
        fontFamily: getFontFamily(false)
      }}
    >
      {/* SVG Filters for Noise Effect */}
      <svg style={{ position: 'absolute', width: 0, height: 0 }}>
        <defs>
          <filter id="noise-0.3">
            <feTurbulence type="fractalNoise" baseFrequency="0.8" numOctaves="4" result="noise" />
            <feColorMatrix in="noise" type="saturate" values="0" />
            <feBlend in="SourceGraphic" in2="noise" mode="multiply" />
          </filter>
          <filter id="noise-0.5">
            <feTurbulence type="fractalNoise" baseFrequency="1.2" numOctaves="4" result="noise" />
            <feColorMatrix in="noise" type="saturate" values="0" />
            <feBlend in="SourceGraphic" in2="noise" mode="multiply" />
          </filter>
          <filter id="noise-0.8">
            <feTurbulence type="fractalNoise" baseFrequency="1.8" numOctaves="4" result="noise" />
            <feColorMatrix in="noise" type="saturate" values="0" />
            <feBlend in="SourceGraphic" in2="noise" mode="multiply" />
          </filter>
        </defs>
      </svg>

      {/* Hamburger Toggle Button */}
      {showHamburger && (
        <button
          onClick={() => setIsOpen(!isOpen)}
          aria-label={isOpen ? "Close menu" : "Open menu"}
          aria-expanded={isOpen}
          style={{
            position: 'fixed',
            top: '40px',
            right: '40px',
            width: '56px',
            height: '56px',
            borderRadius: '50%',
            border: `1px solid ${hamburgerColor}`,
            backgroundColor: backgroundColor,
            cursor: 'pointer',
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '5px',
            padding: 0,
            zIndex: 2000,
            transition: prefersReducedMotion ? 'none' : 'all 250ms ease-out',
            boxShadow: '0 2px 8px rgba(0,0,0,0.08)'
          }}
        >
          <span style={{
            width: '24px',
            height: '2px',
            backgroundColor: hamburgerColor,
            transition: prefersReducedMotion ? 'none' : 'transform 300ms ease, opacity 200ms ease',
            transform: isOpen ? 'translateY(7px) rotate(45deg)' : 'translateY(0) rotate(0)',
            transformOrigin: 'center'
          }} />
          <span style={{
            width: '24px',
            height: '2px',
            backgroundColor: hamburgerColor,
            transition: prefersReducedMotion ? 'none' : 'opacity 200ms ease',
            opacity: isOpen ? 0 : 1
          }} />
          <span style={{
            width: '24px',
            height: '2px',
            backgroundColor: hamburgerColor,
            transition: prefersReducedMotion ? 'none' : 'transform 300ms ease, opacity 200ms ease',
            transform: isOpen ? 'translateY(-7px) rotate(-45deg)' : 'translateY(0) rotate(0)',
            transformOrigin: 'center'
          }} />
        </button>
      )}

      {/* Menu Container */}
      <div
        style={{
          position: 'fixed',
          inset: 0,
          opacity: isOpen ? 1 : 0,
          pointerEvents: isOpen ? 'auto' : 'none',
          transition: prefersReducedMotion ? 'none' : 'opacity 400ms cubic-bezier(0.22, 1, 0.36, 1)',
          zIndex: 1000
        }}
      >
        {/* Menu Items */}
        <div
          style={{
            position: 'relative',
            width: '100%',
            minHeight: '100vh',
            display: layoutMode === 'grid' ? 'grid' : 'flex',
            padding: layoutMode === 'stacked' ? '10vh 8vw' : '0 8vw',
            ...getLayoutStyles()
          }}
        >
          {menuItems.map((item, itemIndex) => {
            const isHovered = hoveredIndex === itemIndex;
            const isActive = activeIndex === itemIndex;
            const isAnimated = animatedIndices.has(itemIndex);
            const isExploding = exploding?.index === itemIndex;
            const parallaxY = getParallaxOffset(itemIndex);
            const isInactive = hoveredIndex !== null && hoveredIndex !== itemIndex;

            const getHoverScale = () => {
              if (!isHovered) return 1;
              if (hoverEffect === 'scale-pulse' || hoverEffect === 'multi') {
                return scalePulseAmount;
              }
              return 1.02;
            };

            return (
              <div
                key={itemIndex}
                ref={el => itemRefs.current[itemIndex] = el}
                onMouseEnter={() => setHoveredIndex(itemIndex)}
                onMouseLeave={() => setHoveredIndex(null)}
                onClick={(e) => handleItemClick(itemIndex, e)}
                role="button"
                tabIndex={isOpen ? 0 : -1}
                aria-label={`${item}: ${menuDescriptors[itemIndex] || ''}`}
                style={{
                  position: 'relative',
                  cursor: 'pointer',
                  opacity: prefersReducedMotion ? 1 : (isAnimated ? (isInactive ? 0.3 : 1) : 0),
                  transform: prefersReducedMotion 
                    ? 'none' 
                    : `translateY(${isAnimated ? parallaxY : 100}px) scale(${isExploding ? 50 : getHoverScale()})`,
                  transition: prefersReducedMotion 
                    ? 'none' 
                    : `opacity 600ms ease-out ${itemIndex * staggerDelay}ms, transform ${isExploding ? explosionDuration : 600}ms ${isExploding ? 'cubic-bezier(0.22, 1, 0.36, 1)' : 'ease-out'} ${isExploding ? 0 : itemIndex * staggerDelay}ms, filter 300ms ease-out`,
                  filter: `${enableInactiveBlur && isInactive ? 'blur(2px)' : 'blur(0)'} ${getGrainFilter(isHovered)}`,
                  willChange: 'transform, opacity',
                  clipPath: isExploding ? `circle(${explosionDuration * 2}px at ${exploding.x}px ${exploding.y}px)` : 'none',
                  zIndex: isHovered ? 10 : (menuItems.length - itemIndex)
                }}
              >
                {/* Background Layer */}
                <div
                  style={{
                    position: 'absolute',
                    inset: '-2vh -4vw',
                    backgroundColor: itemIndex % 2 === 0 ? backgroundColor : secondaryBgColor,
                    opacity: isHovered ? 1 : 0,
                    transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out, box-shadow 300ms ease-out',
                    borderRadius: '4px',
                    pointerEvents: 'none',
                    boxShadow: isHovered ? getDropShadow() : 'none'
                  }}
                />

                {/* Main Typography */}
                <div
                  style={{
                    position: 'relative',
                    fontSize: baseFontSize,
                    fontFamily: getFontFamily(isHovered),
                    fontWeight: enableVariableFontWeight && isHovered && !prefersReducedMotion 
                      ? maxFontWeight 
                      : minFontWeight,
                    letterSpacing: letterSpacing,
                    lineHeight: 0.9,
                    color: isActive ? activeColor : (isHovered ? hoverColor : textColor),
                    textTransform: 'uppercase',
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: '0.5vw',
                    transition: prefersReducedMotion 
                      ? 'none' 
                      : `font-weight ${fontWeightTransitionDuration}ms ease-out, color 300ms ease-out, text-shadow 300ms ease-out, font-family 400ms ease-out`,
                    willChange: 'font-weight, font-family',
                    textShadow: (() => {
                      const effects = [];
                      if (isHovered && !prefersReducedMotion) {
                        const glow = getGlowShadow();
                        const glitch = getGlitchShadow(isHovered);
                        if (glow !== 'none') effects.push(glow);
                        if (glitch !== 'none') effects.push(glitch);
                      }
                      return effects.length > 0 ? effects.join(', ') : 'none';
                    })(),
                    filter: getNoiseFilter()
                  }}
                >
                  {item.split('').map((char, charIndex) => {
                    const [charRect, setCharRect] = React.useState(null);
                    const charRef = React.useRef(null);

                    React.useEffect(() => {
                      if (charRef.current && isHovered) {
                        setCharRect(charRef.current.getBoundingClientRect());
                      }
                    }, [isHovered, mousePos]);

                    const magneticOffset = getMagneticOffset(itemIndex, charIndex, charRect);
                    const charTransform = getCharTransform(itemIndex, charIndex, isHovered);
                    const charOpacity = getCharOpacity(itemIndex, charIndex, isHovered);

                    const combinedTransform = charTransform !== 'none' 
                      ? `translate(${magneticOffset.x}px, ${magneticOffset.y}px) ${charTransform}`
                      : `translate(${magneticOffset.x}px, ${magneticOffset.y}px)`;

                    const getTransitionTiming = () => {
                      if (prefersReducedMotion) return 'none';
                      const speed = getCharAnimSpeed();

                      switch(hoverEffect) {
                        case 'char-rotate':
                          return `transform ${500 * speed}ms ease-out ${charIndex * 30 * speed}ms, opacity 300ms ease-out`;
                        case 'char-stagger':
                          return `transform ${400 * speed}ms ease-out, opacity ${400 * speed}ms ease-out`;
                        case 'char-explode':
                          return `transform ${600 * speed}ms cubic-bezier(0.22, 1, 0.36, 1), opacity 300ms ease-out`;
                        default:
                          return 'transform 150ms ease-out, opacity 300ms ease-out';
                      }
                    };

                    return (
                      <span
                        key={charIndex}
                        ref={charRef}
                        style={{
                          display: 'inline-block',
                          opacity: charOpacity,
                          transform: combinedTransform,
                          transition: getTransitionTiming(),
                          willChange: 'transform, opacity'
                        }}
                      >
                        {char === ' ' ? '\u00A0' : char}
                      </span>
                    );
                  })}
                </div>

                {/* Underline Effect */}
                {(hoverEffect === 'underline' || hoverEffect === 'multi') && (
                  <div
                    style={{
                      position: 'absolute',
                      bottom: layoutMode === 'vertical' ? 'auto' : '-1vh',
                      left: layoutMode === 'vertical' ? '-1vh' : '0',
                      right: layoutMode === 'vertical' ? 'auto' : 'auto',
                      top: layoutMode === 'vertical' ? '0' : 'auto',
                      width: layoutMode === 'vertical' ? `${underlineThickness}px` : (isHovered ? '100%' : '0%'),
                      height: layoutMode === 'vertical' ? (isHovered ? '100%' : '0%') : `${underlineThickness}px`,
                      backgroundColor: hoverColor,
                      transition: prefersReducedMotion ? 'none' : 'width 400ms ease-out, height 400ms ease-out',
                      transformOrigin: layoutMode === 'vertical' ? 'top' : 'left'
                    }}
                  />
                )}

                {/* Descriptor */}
                {menuDescriptors[itemIndex] && layoutMode !== 'vertical' && (
                  <div
                    style={{
                      position: 'relative',
                      fontSize: `${descriptorFontSize}px`,
                      fontWeight: '300',
                      color: descriptorColor,
                      letterSpacing: '0.05em',
                      marginTop: '1vh',
                      marginLeft: '0.5vw',
                      opacity: isHovered ? 1 : 0.7,
                      transform: `translateX(${isHovered ? 10 : 0}px)`,
                      transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out, transform 300ms ease-out'
                    }}
                  >
                    {menuDescriptors[itemIndex]}
                  </div>
                )}

                {/* Number Index */}
                {layoutMode !== 'vertical' && (
                  <div
                    style={{
                      position: 'absolute',
                      right: '4vw',
                      top: '50%',
                      transform: 'translateY(-50%)',
                      fontSize: '14px',
                      fontWeight: '300',
                      color: descriptorColor,
                      opacity: isHovered ? 1 : 0.5,
                      transition: prefersReducedMotion ? 'none' : 'opacity 300ms ease-out'
                    }}
                  >
                    {String(itemIndex + 1).padStart(2, '0')}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>

      {/* Scroll Indicator */}
      {isOpen && layoutMode === 'horizontal' && (
        <div
          style={{
            position: 'fixed',
            bottom: '40px',
            left: '50%',
            transform: 'translateX(-50%)',
            fontSize: '12px',
            fontWeight: '300',
            color: descriptorColor,
            letterSpacing: '0.1em',
            textTransform: 'uppercase',
            opacity: scrollY > 100 ? 0 : 1,
            transition: 'opacity 400ms ease-out',
            pointerEvents: 'none',
            zIndex: 1001
          }}
        >
          Scroll to Explore
        </div>
      )}
    </div>
  );
}

navigation-morphheader:
/*
 * COMPONENT: Navigation.MorphHeader
 * CONCEPT: A header that condenses into a floating pill as the user scrolls.
 * TECH: Scroll event listener mapping scrollY to CSS variables.
 */

const MANIFEST = {
  "type": "Navigation.MorphHeader",
  "description": "Header that shrinks and reshapes on scroll.",
  "editorElement": {
    "selector": ".morph-header",
    "displayName": "Morphing Header",
    "archetype": "container",
    "data": {
      "companyName": { "dataType": "text", "defaultValue": "ACME INC.", "group": "Content" },
      "links": { "dataType": "text", "defaultValue": "Work,About,Careers", "group": "Content" },
      "primaryColor": { "dataType": "color", "defaultValue": "#000000", "group": "Colors" },
      "backgroundColor": { "dataType": "color", "defaultValue": "#FFFFFF", "group": "Colors" }
    }
  }
};

function Component({ config = {} }) {
  const name = config?.companyName || "ACME INC.";
  const links = (config?.links || "Work,About,Careers").split(',');
  const color = config?.primaryColor || "#000000";
  const bg = config?.backgroundColor || "#FFFFFF";

  const [scroll, setScroll] = React.useState(0);

  React.useEffect(() => {
    const handleScroll = () => {
      // Clamp scroll value for animation range (0 to 100px)
      setScroll(Math.min(100, window.scrollY));
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Calculate morph values
  const progress = scroll / 100;
  // Width: 100% -> 300px (approx)
  const width = `calc(100% - ${progress * (window.innerWidth < 600 ? 40 : 600)}px)`; 
  const top = progress * 20;
  const radius = progress * 50;
  const padding = 24 - (progress * 10); // 24px -> 14px

  return (
    <div style={{ height: '150vh', backgroundColor: '#F3F4F6', position: 'relative' }}>

      {/* Sticky Header */}
      <div style={{
        position: 'fixed',
        top: `${top}px`,
        left: '50%',
        transform: 'translateX(-50%)',
        width: width,
        maxWidth: '1200px',
        backgroundColor: bg,
        borderRadius: `${radius}px`,
        padding: `${padding}px 40px`,
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        boxShadow: `0 ${progress * 10}px ${progress * 30}px rgba(0,0,0,0.1)`,
        transition: 'all 0.1s linear', // Fast response to scroll
        zIndex: 100
      }}>

        {/* Logo Area */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div style={{ 
            width: '32px', height: '32px', background: color, borderRadius: '50%', flexShrink: 0 
          }} />
          <span style={{ 
            fontSize: '20px', fontWeight: '800', color: color,
            opacity: 1 - progress, // Fade out name
            width: (1 - progress) * 120 + 'px', // Collapse width
            overflow: 'hidden', whiteSpace: 'nowrap',
            transition: 'opacity 0.1s, width 0.1s'
          }}>
            {name}
          </span>
        </div>

        {/* Navigation */}
        <div style={{ display: 'flex', gap: '24px' }}>
          {links.map((link, i) => (
            <a key={i} href="#" style={{ 
              textDecoration: 'none', color: color, fontWeight: '500', fontSize: '14px',
              opacity: 1 - (progress * 0.3) // Slight dim on scroll
            }}>
              {link}
            </a>
          ))}
        </div>

        {/* CTA Button (appears on scroll) */}
        <div style={{
          width: progress * 100 + 'px',
          overflow: 'hidden',
          opacity: progress,
          transition: 'all 0.1s'
        }}>
          <button style={{
            width: '100px',
            padding: '8px 16px',
            backgroundColor: color,
            color: bg,
            border: 'none',
            borderRadius: '20px',
            fontSize: '12px',
            fontWeight: 'bold',
            cursor: 'pointer',
            whiteSpace: 'nowrap'
          }}>
            Get App
          </button>
        </div>

      </div>

      {/* Placeholder Content */}
      <div style={{ paddingTop: '150px', paddingLeft: '40px', color: '#9CA3AF' }}>
        <p>Scroll down to see the header morph into a floating pill UI.</p>
      </div>
    </div>
  );
}

navigation-tiltmegamenu:
/*
 * COMPONENT: Navigation.TiltMegaMenu
 * CONCEPT: A mega menu where featured items react to mouse hover with a 3D tilt effect.
 * TECH: Mouse tracking per card to calculate rotation angles.
 */

const MANIFEST = {
  "type": "Navigation.TiltMegaMenu",
  "description": "Glassmorphism mega menu with 3D interactive cards.",
  "editorElement": {
    "selector": ".tilt-menu",
    "displayName": "Tilt Mega Menu",
    "archetype": "container",
    "data": {
      "triggerLabel": { "dataType": "text", "defaultValue": "Products", "group": "Content" },
      "card1Title": { "dataType": "text", "defaultValue": "Analytics", "group": "Content" },
      "card2Title": { "dataType": "text", "defaultValue": "Automation", "group": "Content" },
      "accentColor": { "dataType": "color", "defaultValue": "#8B5CF6", "group": "Colors" }
    }
  }
};

const TiltCard = ({ title, subtitle, color }) => {
  const ref = React.useRef(null);
  const [rot, setRot] = React.useState({ x: 0, y: 0 });

  const handleMove = (e) => {
    const rect = ref.current.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const rotateX = ((y - centerY) / centerY) * -10; // Max 10deg
    const rotateY = ((x - centerX) / centerX) * 10;

    setRot({ x: rotateX, y: rotateY });
  };

  const handleLeave = () => setRot({ x: 0, y: 0 });

  return (
    <div
      ref={ref}
      onMouseMove={handleMove}
      onMouseLeave={handleLeave}
      style={{
        flex: 1,
        height: '200px',
        borderRadius: '12px',
        backgroundColor: 'rgba(255,255,255,0.1)',
        border: '1px solid rgba(255,255,255,0.2)',
        padding: '24px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'flex-end',
        transform: `perspective(1000px) rotateX(${rot.x}deg) rotateY(${rot.y}deg)`,
        transition: 'transform 0.1s ease-out',
        cursor: 'pointer',
        boxShadow: '0 10px 30px rgba(0,0,0,0.1)'
      }}
    >
      <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: color, marginBottom: 'auto' }} />
      <h3 style={{ margin: '0 0 8px 0', fontSize: '18px', color: '#fff' }}>{title}</h3>
      <p style={{ margin: 0, fontSize: '12px', color: 'rgba(255,255,255,0.6)' }}>{subtitle}</p>
    </div>
  );
};

function Component({ config = {} }) {
  const trigger = config?.triggerLabel || "Products";
  const t1 = config?.card1Title || "Analytics";
  const t2 = config?.card2Title || "Automation";
  const accent = config?.accentColor || "#8B5CF6";

  const [isOpen, setIsOpen] = React.useState(false);

  return (
    <div style={{ padding: '50px', backgroundColor: '#0F172A', minHeight: '500px', display: 'flex', justifyContent: 'center' }}>

      <div style={{ position: 'relative' }} onMouseLeave={() => setIsOpen(false)}>
        <button
          onMouseEnter={() => setIsOpen(true)}
          style={{
            padding: '12px 24px',
            fontSize: '16px',
            fontWeight: '600',
            color: '#fff',
            backgroundColor: 'transparent',
            border: 'none',
            cursor: 'pointer'
          }}
        >
          {trigger}
        </button>

        {/* Dropdown */}
        <div style={{
          position: 'absolute',
          top: '100%',
          left: '50%',
          transform: `translateX(-50%) translateY(${isOpen ? 0 : 20}px)`,
          opacity: isOpen ? 1 : 0,
          pointerEvents: isOpen ? 'auto' : 'none',
          transition: 'all 0.3s cubic-bezier(0.165, 0.84, 0.44, 1)',
          width: '600px',
          padding: '24px',
          borderRadius: '24px',
          backgroundColor: 'rgba(30, 41, 59, 0.7)',
          backdropFilter: 'blur(20px)',
          border: '1px solid rgba(255,255,255,0.1)',
          display: 'flex',
          gap: '20px',
          boxShadow: '0 20px 50px rgba(0,0,0,0.3)'
        }}>
          {/* List Section */}
          <div style={{ width: '150px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {['Overview', 'Pricing', 'Customers', 'Updates'].map(item => (
              <a key={item} href="#" style={{ color: '#94A3B8', textDecoration: 'none', fontSize: '14px', padding: '8px', borderRadius: '8px', transition: 'background 0.2s' }}
                 onMouseEnter={e => { e.target.style.background = 'rgba(255,255,255,0.05)'; e.target.style.color = '#fff'; }}
                 onMouseLeave={e => { e.target.style.background = 'transparent'; e.target.style.color = '#94A3B8'; }}>
                {item}
              </a>
            ))}
          </div>

          {/* Cards Section */}
          <TiltCard title={t1} subtitle="Real-time data insights" color={accent} />
          <TiltCard title={t2} subtitle="AI-powered workflows" color="#10B981" />
        </div>
      </div>
    </div>
  );
}
